#!/usr/bin/env python3
"""ci-wait.py — Gate a task until its PR's observed checks are terminal.

Usage: python3 factory/scripts/ci-wait.py <lane-name>

Resolves the PR whose head branch equals the lane name, then waits until the
complete current-head check set observed by review is terminal (pass, fail,
cancelled, or skipped). Verdicts are the reviewer's job: this gate does NOT
care whether checks passed, only that they finished, so reviewer agent sessions
never spend time or review-loop visits watching CI.

Outcome contract (script workers signal via exit code only):
  exit 0 -> task moves to in-review (success output)
  exit 1 -> task moves to failed (failure output)

Because the runtime gives script workers no CONTINUE outcome, this script is
one-shot: it polls internally every POLL_INTERVAL_SECONDS and exits 0 either
when checks are terminal or when the internal DEADLINE_SECONDS budget (kept
well below the runtime's 2h hard worker-execution timeout) runs out. On a
deadline exit the reviewer will observe still-pending checks and end with a
hold, which routes the task back through this gate — a cheap, bounded
re-queue rather than a lane-killing failure.

Special cases:
  - No PR yet: successful lookups that return no matching PR may race a
    processor push; retry for ~2 minutes, then exit 1 with a clear stderr
    message.
  - GitHub lookup unavailable: retry a bounded infrastructure budget with
    backoff, then exit 0 for the review hold-and-requeue path.
  - PR already MERGED (and no open PR for the branch): exit 0 immediately;
    the review workstation's merged-PR short-circuit handles the rest.
  - Only CLOSED PRs: exit 0 immediately; the reviewer decides what a closed,
    unmerged PR means for the lane.
  - No checks reported: tolerated for NO_CHECKS_GRACE_SECONDS (checks can
    lag a fresh push), then released with an explicit no-checks reason so the
    reviewer sees reality. It is never treated as checks-terminal.

Stdlib-only; shells out to the `gh` CLI like setup-workspace.py does for git.
"""

import json
import subprocess
import sys
import time
from dataclasses import dataclass
from enum import Enum

POLL_INTERVAL_SECONDS = 120
DEADLINE_SECONDS = 100 * 60  # one-shot budget, well below the 2h hard timeout
GH_CALL_TIMEOUT_SECONDS = 120
PR_LOOKUP_ATTEMPTS = 5
PR_LOOKUP_INTERVAL_SECONDS = 30  # ~2 minutes of retries for a just-pushed PR
PR_LOOKUP_INFRASTRUCTURE_ATTEMPTS = 3
PR_LOOKUP_INFRASTRUCTURE_BACKOFF_SECONDS = 5
PR_LOOKUP_INFRASTRUCTURE_MAX_BACKOFF_SECONDS = 60
NO_CHECKS_GRACE_SECONDS = 10 * 60
PR_VIEW_JSON_FIELDS = "number,state,headRefOid,statusCheckRollup"
PR_CHECKS_JSON_FIELDS = "name,state,bucket,link,workflow,startedAt,completedAt"
CONVERGENCE_OBSERVATIONS = 2

NON_TERMINAL_BUCKETS = {"pending"}
NON_TERMINAL_STATES = {"PENDING", "QUEUED", "IN_PROGRESS", "WAITING", "REQUESTED", "EXPECTED"}
TERMINAL_STATES = {
    "ACTION_REQUIRED",
    "CANCELLED",
    "ERROR",
    "FAILURE",
    "NEUTRAL",
    "SKIPPED",
    "STALE",
    "STARTUP_FAILURE",
    "SUCCESS",
    "TIMED_OUT",
}
KNOWN_CHECK_BUCKETS = {"cancel", "fail", "pass", "pending", "skipping"}
PR_STATE_PREFERENCE = ("OPEN", "MERGED", "CLOSED")


class PRLookupStatus(Enum):
    """Classification of a GitHub PR lookup response."""

    FOUND = "found"
    NOT_FOUND = "not-found"
    INFRASTRUCTURE_FAILURE = "infrastructure-failure"


@dataclass(frozen=True)
class PRLookupResult:
    """A typed result that keeps an empty response distinct from a failure."""

    status: PRLookupStatus
    prs: tuple = ()


class JSONReadStatus(Enum):
    """Classification of one bounded JSON response from gh."""

    OK = "ok"
    EMPTY = "empty"
    MALFORMED = "malformed"
    UNAVAILABLE = "unavailable"


@dataclass(frozen=True)
class JSONRead:
    """A parsed gh response with an explicit failure classification."""

    status: JSONReadStatus
    value: object = None


class SnapshotStatus(Enum):
    """Classification of the reconciled current-head observation."""

    VALID = "valid"
    EMPTY = "empty"
    UNCERTAIN = "uncertain"


@dataclass(frozen=True)
class CurrentHeadSnapshot:
    """One bounded, same-head observation of the review-visible check set."""

    status: SnapshotStatus
    reason: str
    head_ref_oid: str = ""
    checks: tuple = ()
    observed_heads: tuple = ()

    def fingerprint(self):
        """Return the stable evidence used for convergence across snapshots."""
        return (
            self.head_ref_oid,
            tuple(
                (
                    check["identity"],
                    check["state"],
                    check["bucket"],
                    check.get("link"),
                    check.get("workflow"),
                )
                for check in self.checks
            ),
        )


def log(message):
    """Log progress to stderr; stdout is reserved for the final JSON result."""
    print(message, file=sys.stderr, flush=True)


def run_gh(*args):
    """Run a gh command, returning the CompletedProcess. Never raises on rc."""
    return subprocess.run(
        ["gh", *args],
        capture_output=True,
        text=True,
        timeout=GH_CALL_TIMEOUT_SECONDS,
    )


def list_prs_for_head(branch):
    """Return a typed result for the lane's GitHub PR lookup."""
    try:
        result = run_gh(
            "pr", "list",
            "--head", branch,
            "--state", "all",
            "--json", "number,state",
            "--limit", "20",
        )
    except subprocess.TimeoutExpired:
        log("gh pr list timed out; treating lookup as an infrastructure failure")
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)
    except OSError:
        log("gh pr list could not be executed; treating lookup as an infrastructure failure")
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)

    if result.returncode != 0:
        log(
            f"gh pr list failed (exit {result.returncode}); "
            "treating lookup as an infrastructure failure"
        )
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)

    stdout = (result.stdout or "").strip()
    if not stdout:
        log(
            "gh pr list returned no output; treating lookup as an infrastructure "
            "failure"
        )
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)

    try:
        prs = json.loads(stdout)
    except (TypeError, json.JSONDecodeError):
        log(
            "gh pr list returned unparseable JSON; treating lookup as an "
            "infrastructure failure"
        )
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)

    if not isinstance(prs, list) or any(
        not isinstance(pr, dict)
        or not isinstance(pr.get("number"), int)
        or pr.get("state") not in PR_STATE_PREFERENCE
        for pr in prs
    ):
        log(
            "gh pr list returned unusable JSON; treating lookup as an infrastructure "
            "failure"
        )
        return PRLookupResult(PRLookupStatus.INFRASTRUCTURE_FAILURE)

    status = PRLookupStatus.FOUND if prs else PRLookupStatus.NOT_FOUND
    return PRLookupResult(status, tuple(prs))


def infrastructure_backoff_seconds(attempt):
    """Return bounded exponential backoff for an infrastructure retry."""
    return min(
        PR_LOOKUP_INFRASTRUCTURE_BACKOFF_SECONDS * (2 ** (attempt - 1)),
        PR_LOOKUP_INFRASTRUCTURE_MAX_BACKOFF_SECONDS,
    )


def release_for_infrastructure_requeue(branch, attempts):
    """Emit the successful result that routes dependency failure to review."""
    log(
        f"ci-wait: GitHub PR lookup infrastructure retry budget exhausted "
        f"for head branch {branch!r} after {attempts} failures; releasing to "
        "review for hold-and-requeue"
    )
    emit_result(
        branch=branch,
        reason="pr-lookup-infrastructure-requeue",
        lookup=PRLookupStatus.INFRASTRUCTURE_FAILURE.value,
        infrastructureAttempts=attempts,
    )


def resolve_pr(branch):
    """Resolve the lane's PR with separate absence and infrastructure budgets.

    Returns a dict {number, state} for the PR to gate on, preferring an OPEN
    PR, then MERGED, then CLOSED. Exits 1 when successful empty lookups exhaust
    the missing-PR budget. Returns None after an infrastructure budget is
    exhausted, having emitted the exit-0 requeue result.
    """
    successful_empty_lookups = 0
    infrastructure_failures = 0
    while successful_empty_lookups < PR_LOOKUP_ATTEMPTS:
        lookup = list_prs_for_head(branch)
        if lookup.status == PRLookupStatus.INFRASTRUCTURE_FAILURE:
            infrastructure_failures += 1
            if infrastructure_failures >= PR_LOOKUP_INFRASTRUCTURE_ATTEMPTS:
                release_for_infrastructure_requeue(branch, infrastructure_failures)
                return None

            backoff = infrastructure_backoff_seconds(infrastructure_failures)
            log(
                f"ci-wait: GitHub PR lookup infrastructure failure for head branch "
                f"{branch!r} (attempt {infrastructure_failures}/"
                f"{PR_LOOKUP_INFRASTRUCTURE_ATTEMPTS}); retrying in {backoff}s"
            )
            time.sleep(backoff)
            continue

        # A successful response means the dependency recovered. Do not let
        # earlier transport failures consume the separate infrastructure
        # budget or change the meaning of this response.
        infrastructure_failures = 0

        if lookup.status == PRLookupStatus.NOT_FOUND:
            successful_empty_lookups += 1
            log(
                f"successful PR lookup found no matching PR for head branch "
                f"{branch!r} (successful empty lookup "
                f"{successful_empty_lookups}/{PR_LOOKUP_ATTEMPTS})"
            )
            if successful_empty_lookups < PR_LOOKUP_ATTEMPTS:
                log(
                    f"ci-wait: retrying successful empty PR lookup for head branch "
                    f"{branch!r} in {PR_LOOKUP_INTERVAL_SECONDS}s"
                )
                time.sleep(PR_LOOKUP_INTERVAL_SECONDS)
            continue

        for state in PR_STATE_PREFERENCE:
            matches = [pr for pr in lookup.prs if pr.get("state") == state]
            if matches:
                return matches[0]

        # Valid gh output currently has only OPEN, MERGED, or CLOSED states,
        # so reaching this point would indicate a future response shape that
        # cannot be selected safely. Treat it like an infrastructure failure
        # without spending a successful-not-found attempt.
        infrastructure_failures += 1
        log(
            f"ci-wait: GitHub PR lookup returned no selectable PR for head branch "
            f"{branch!r}; treating response as an infrastructure failure"
        )
        if infrastructure_failures >= PR_LOOKUP_INFRASTRUCTURE_ATTEMPTS:
            release_for_infrastructure_requeue(branch, infrastructure_failures)
            return None
        backoff = infrastructure_backoff_seconds(infrastructure_failures)
        time.sleep(backoff)

    print(
        f"ci-wait: successful PR lookups found no PR for head branch "
        f"{branch!r} after {successful_empty_lookups} successful lookups. "
        "The process workstation must open a PR named after the lane before "
        "the task can enter review.",
        file=sys.stderr,
    )
    sys.exit(1)


def read_gh_json(label, *args):
    """Read one JSON response without leaking dependency stderr or payloads."""
    try:
        result = run_gh(*args)
    except subprocess.TimeoutExpired:
        log(f"{label} timed out; treating the observation as unavailable")
        return JSONRead(JSONReadStatus.UNAVAILABLE)
    except OSError:
        log(f"{label} could not be executed; treating the observation as unavailable")
        return JSONRead(JSONReadStatus.UNAVAILABLE)

    stdout = (result.stdout or "").strip()
    if not stdout:
        status = JSONReadStatus.UNAVAILABLE if result.returncode else JSONReadStatus.EMPTY
        log(
            f"{label} returned no JSON (exit {result.returncode}); "
            f"treating the observation as {status.value}"
        )
        return JSONRead(status)

    try:
        value = json.loads(stdout)
    except (TypeError, json.JSONDecodeError) as error:
        position = error.pos if hasattr(error, "pos") else "?"
        log(f"{label} returned unparseable JSON at position {position}")
        return JSONRead(JSONReadStatus.MALFORMED)

    # gh pr checks uses nonzero exits for pending (8) and failing (1) checks.
    # A schema-valid stdout response remains useful regardless of that signal.
    return JSONRead(JSONReadStatus.OK, value)


def fetch_pr_view(pr_number):
    """Read the PR head and status-check rollup for one bounded observation."""
    return read_gh_json(
        "gh pr view",
        "pr",
        "view",
        str(pr_number),
        "--json",
        PR_VIEW_JSON_FIELDS,
    )


def fetch_checks(pr_number):
    """Read the full review-observed check list; required-only is not used."""
    return read_gh_json(
        "gh pr checks",
        "pr",
        "checks",
        str(pr_number),
        "--json",
        PR_CHECKS_JSON_FIELDS,
    )


def _non_empty_text(value):
    """Return a stripped string or None for an absent/invalid text field."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    return value or None


def _check_kind(check, source):
    """Return the stable GitHub check type used in an identity."""
    explicit_kind = check.get("__typename") or check.get("type") or check.get("kind")
    if explicit_kind is not None:
        if explicit_kind in {"CheckRun", "StatusContext"}:
            return explicit_kind
        return None
    if _non_empty_text(check.get("context")):
        return "StatusContext"
    if source == "checks" or _non_empty_text(check.get("name")):
        return "CheckRun"
    return None


def _check_state(check):
    """Normalize gh check-run/status states into a terminality vocabulary."""
    raw_state = check.get("state")
    if raw_state is None:
        raw_state = check.get("status")
    state = _non_empty_text(raw_state)
    conclusion = _non_empty_text(check.get("conclusion"))
    if state:
        state = state.upper().replace("-", "_")
    if conclusion:
        conclusion = conclusion.upper().replace("-", "_")

    if state in {"COMPLETED", "COMPLETE", "DONE"}:
        state = conclusion
    elif state is None:
        state = conclusion

    if state == "CANCELED":
        state = "CANCELLED"
    return state


def _canonical_bucket(state):
    """Map a known state to the conservative review bucket."""
    if state in NON_TERMINAL_STATES:
        return "pending"
    if state == "SUCCESS":
        return "pass"
    if state in {"NEUTRAL", "SKIPPED"}:
        return "skipping"
    return "fail"


def _normalize_check(check, source):
    """Return one identity-complete check row or a bounded rejection reason."""
    if not isinstance(check, dict):
        return None, "malformed-check-row"

    kind = _check_kind(check, source)
    if kind is None:
        return None, "unknown-check-type"
    name = _non_empty_text(check.get("name")) or _non_empty_text(check.get("context"))
    if name is None:
        return None, "unknown-check-name"

    link = None
    for field in ("link", "detailsUrl", "targetUrl", "url", "htmlUrl"):
        link = _non_empty_text(check.get(field))
        if link:
            break
    workflow = _non_empty_text(check.get("workflow")) or _non_empty_text(
        check.get("workflowName")
    )
    stable_ref = link
    if stable_ref is None and workflow is not None:
        stable_ref = f"workflow:{workflow}"
    if stable_ref is None and kind == "StatusContext":
        stable_ref = f"context:{name}"
    if stable_ref is None:
        return None, "unknown-check-identity"

    state = _check_state(check)
    if state not in NON_TERMINAL_STATES and state not in TERMINAL_STATES:
        return None, "unknown-check-state"
    bucket = _canonical_bucket(state)
    supplied_bucket = check.get("bucket")
    if supplied_bucket is not None:
        supplied_bucket = _non_empty_text(supplied_bucket)
        if supplied_bucket is None or supplied_bucket.lower() not in KNOWN_CHECK_BUCKETS:
            return None, "unknown-check-bucket"
        supplied_bucket = supplied_bucket.lower()
        if supplied_bucket != bucket and not (
            state == "CANCELLED" and supplied_bucket == "cancel"
        ):
            return None, "check-state-bucket-mismatch"

    identity = f"{kind}|{name}|{stable_ref}"
    return (
        {
            "identity": identity,
            "name": name,
            "workflow": workflow,
            "link": link,
            "state": state,
            "bucket": bucket,
        },
        None,
    )


def _normalize_check_list(checks, source):
    """Normalize a non-empty check list and reject duplicate/unknown rows."""
    if not isinstance(checks, list):
        return None, "malformed-check-list"
    normalized = {}
    for check in checks:
        normalized_check, reason = _normalize_check(check, source)
        if normalized_check is None:
            return None, reason
        identity = normalized_check["identity"]
        if identity in normalized:
            return None, "duplicate-check-identity"
        normalized[identity] = normalized_check
    return normalized, None


def _merge_check_maps(left, right, require_same_keys=False):
    """Reconcile two normalized sources without hiding state changes."""
    if require_same_keys and set(left) != set(right):
        return None, "check-set-changed-during-observation"

    merged = {}
    for identity in sorted(set(left) | set(right)):
        left_check = left.get(identity)
        right_check = right.get(identity)
        if left_check is not None and right_check is not None:
            if (
                left_check["state"] != right_check["state"]
                or left_check["bucket"] != right_check["bucket"]
            ):
                return None, "check-state-mismatch"
            check = dict(left_check)
            if check["link"] is None:
                check["link"] = right_check["link"]
            if check["workflow"] is None:
                check["workflow"] = right_check["workflow"]
            merged[identity] = check
        else:
            merged[identity] = dict(left_check or right_check)
    return merged, None


def _view_parts(read, pr_number):
    """Validate and unpack one PR view response."""
    if read.status != JSONReadStatus.OK:
        return None, f"view-{read.status.value}"
    if not isinstance(read.value, dict):
        return None, "malformed-pr-view"
    if read.value.get("number") != pr_number:
        return None, "pr-number-mismatch"
    if _non_empty_text(read.value.get("state")) != "OPEN":
        return None, "pr-state-changed"
    head_ref_oid = _non_empty_text(read.value.get("headRefOid"))
    if head_ref_oid is None:
        return None, "unknown-head"
    rollup = read.value.get("statusCheckRollup")
    if not isinstance(rollup, list):
        return None, "malformed-status-check-rollup"
    return (head_ref_oid, rollup), None


def _head_hint(read):
    """Extract a safe head hint for a bounded diagnostic."""
    if read.status == JSONReadStatus.OK and isinstance(read.value, dict):
        return _non_empty_text(read.value.get("headRefOid")) or ""
    return ""


def _observed_heads(*heads):
    """Keep ordered, non-empty head identities without duplicates."""
    return tuple(dict.fromkeys(head for head in heads if head))


def observe_current_head(pr_number):
    """Take one bounded before/checks/after observation of the PR."""
    before_read = fetch_pr_view(pr_number)
    checks_read = fetch_checks(pr_number)
    after_read = fetch_pr_view(pr_number)

    before, before_reason = _view_parts(before_read, pr_number)
    after, after_reason = _view_parts(after_read, pr_number)
    before_head = before[0] if before else _head_hint(before_read)
    after_head = after[0] if after else _head_hint(after_read)
    heads = _observed_heads(before_head, after_head)
    head_ref_oid = after_head or before_head

    if before_reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"before-{before_reason}",
            head_ref_oid,
            observed_heads=heads,
        )
    if after_reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"after-{after_reason}",
            head_ref_oid,
            observed_heads=heads,
        )
    if before_head != after_head:
        log(
            f"PR #{pr_number} head changed during checks observation: "
            f"{before_head} -> {after_head}"
        )
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            "head-changed-during-observation",
            after_head,
            observed_heads=heads,
        )

    checks = checks_read.value if checks_read.status == JSONReadStatus.OK else None
    if checks_read.status != JSONReadStatus.OK:
        if not before[1] and not after[1] and checks_read.status == JSONReadStatus.EMPTY:
            return CurrentHeadSnapshot(
                SnapshotStatus.EMPTY,
                "empty-current-head-check-set",
                head_ref_oid,
                observed_heads=heads,
            )
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"checks-{checks_read.status.value}",
            head_ref_oid,
            observed_heads=heads,
        )
    if not isinstance(checks, list):
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            "malformed-check-list",
            head_ref_oid,
            observed_heads=heads,
        )
    if not before[1] or not after[1] or not checks:
        if not before[1] and not after[1] and not checks:
            return CurrentHeadSnapshot(
                SnapshotStatus.EMPTY,
                "empty-current-head-check-set",
                head_ref_oid,
                observed_heads=heads,
            )
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            "incomplete-current-head-check-set",
            head_ref_oid,
            observed_heads=heads,
        )

    before_map, reason = _normalize_check_list(before[1], "rollup")
    if reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"before-{reason}",
            head_ref_oid,
            observed_heads=heads,
        )
    after_map, reason = _normalize_check_list(after[1], "rollup")
    if reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"after-{reason}",
            head_ref_oid,
            checks=tuple(before_map.values()),
            observed_heads=heads,
        )
    checks_map, reason = _normalize_check_list(checks, "checks")
    if reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            f"checks-{reason}",
            head_ref_oid,
            checks=tuple(sorted(before_map.values(), key=lambda check: check["identity"])),
            observed_heads=heads,
        )

    rollup_map, reason = _merge_check_maps(
        before_map,
        after_map,
        require_same_keys=True,
    )
    if reason is not None:
        diagnostic_checks = before_map
        if reason == "check-set-changed-during-observation":
            # The union is diagnostic only: the differing snapshots remain
            # uncertain and cannot be used as terminal evidence. Including
            # both sides makes a delayed registration visible to review.
            diagnostic_checks, _ = _merge_check_maps(before_map, after_map)
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            reason,
            head_ref_oid,
            checks=tuple(
                sorted(
                    diagnostic_checks.values(), key=lambda check: check["identity"]
                )
            ),
            observed_heads=heads,
        )
    reconciled, reason = _merge_check_maps(rollup_map, checks_map)
    if reason is not None:
        return CurrentHeadSnapshot(
            SnapshotStatus.UNCERTAIN,
            reason,
            head_ref_oid,
            checks=tuple(sorted(reconciled.values(), key=lambda check: check["identity"]))
            if reconciled
            else tuple(sorted(rollup_map.values(), key=lambda check: check["identity"])),
            observed_heads=heads,
        )

    return CurrentHeadSnapshot(
        SnapshotStatus.VALID,
        "stable-current-head-observation",
        head_ref_oid,
        checks=tuple(reconciled[identity] for identity in sorted(reconciled)),
        observed_heads=heads,
    )


def non_terminal_checks(checks):
    """Return the subset of normalized checks that have not finished."""
    pending = []
    for check in checks:
        if not isinstance(check, dict):
            pending.append(check)
            continue
        bucket = str(check.get("bucket", "")).lower()
        state = str(check.get("state", "")).upper()
        if bucket in NON_TERMINAL_BUCKETS or state in NON_TERMINAL_STATES:
            pending.append(check)
    return pending


def emit_result(**fields):
    print(json.dumps({"status": "ready", **fields}, indent=2))


def snapshot_fields(snapshot):
    """Return additive, review-visible evidence for a snapshot."""
    fields = {
        "checks": len(snapshot.checks),
        "headRefOid": snapshot.head_ref_oid or None,
        "checkIdentities": list(snapshot.checks),
    }
    pending = non_terminal_checks(snapshot.checks)
    if pending:
        fields["pendingChecks"] = pending
    return fields


def snapshot_uncertainty(snapshot, reason=None):
    """Return bounded uncertainty without treating it as terminal evidence."""
    uncertainty = {"reason": reason or snapshot.reason}
    if snapshot.head_ref_oid:
        uncertainty["headRefOid"] = snapshot.head_ref_oid
    if snapshot.observed_heads:
        uncertainty["observedHeads"] = list(snapshot.observed_heads)
    return uncertainty


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <lane-name>", file=sys.stderr)
        sys.exit(1)

    branch = sys.argv[1]
    pr = resolve_pr(branch)
    if pr is None:
        return
    pr_number = pr.get("number")
    pr_state = pr.get("state")

    if pr_state == "MERGED":
        log(f"PR #{pr_number} for {branch!r} is already MERGED; releasing to review")
        emit_result(pr=pr_number, prState=pr_state, reason="pr-merged")
        return

    if pr_state == "CLOSED":
        log(f"only CLOSED PRs exist for {branch!r} (newest #{pr_number}); releasing to review")
        emit_result(pr=pr_number, prState=pr_state, reason="pr-closed")
        return

    deadline = time.monotonic() + DEADLINE_SECONDS
    no_checks_deadline = time.monotonic() + NO_CHECKS_GRACE_SECONDS
    candidate_fingerprint = None
    convergence_count = 0
    while True:
        snapshot = observe_current_head(pr_number)
        now = time.monotonic()
        pending = non_terminal_checks(snapshot.checks)

        if snapshot.status == SnapshotStatus.VALID:
            if pending:
                candidate_fingerprint = None
                convergence_count = 0
                names = ", ".join(
                    f"{check.get('name', '?')}="
                    f"{check.get('state', '?')} ({check.get('identity', '?')})"
                    for check in pending[:5]
                )
                log(
                    f"PR #{pr_number} current head {snapshot.head_ref_oid}: "
                    f"{len(pending)} non-terminal check(s): {names}"
                )
            else:
                fingerprint = snapshot.fingerprint()
                if fingerprint == candidate_fingerprint:
                    convergence_count += 1
                else:
                    candidate_fingerprint = fingerprint
                    convergence_count = 1
                if convergence_count >= CONVERGENCE_OBSERVATIONS:
                    log(
                        f"all {len(snapshot.checks)} checks on current head "
                        f"{snapshot.head_ref_oid} are terminal after "
                        f"{convergence_count} stable observations"
                    )
                    emit_result(
                        pr=pr_number,
                        prState=pr_state,
                        reason="checks-terminal",
                        **snapshot_fields(snapshot),
                        uncertainty=None,
                    )
                    return
                log(
                    f"PR #{pr_number} current head {snapshot.head_ref_oid}: "
                    f"terminal candidate observed; awaiting same-head convergence "
                    f"({convergence_count}/{CONVERGENCE_OBSERVATIONS})"
                )
        elif snapshot.status == SnapshotStatus.EMPTY:
            candidate_fingerprint = None
            convergence_count = 0
            if snapshot.reason == "empty-current-head-check-set" and now >= no_checks_deadline:
                log(
                    f"PR #{pr_number} current head {snapshot.head_ref_oid or 'unknown'} "
                    f"reports no checks after {NO_CHECKS_GRACE_SECONDS // 60} minutes; "
                    "releasing with explicit no-check uncertainty"
                )
                emit_result(
                    pr=pr_number,
                    prState=pr_state,
                    reason="no-checks-reported",
                    **snapshot_fields(snapshot),
                    uncertainty=snapshot_uncertainty(snapshot),
                )
                return
            log(
                f"PR #{pr_number} current head {snapshot.head_ref_oid or 'unknown'}: "
                "no complete check set reported yet; waiting for CI to register"
            )
        else:
            candidate_fingerprint = None
            convergence_count = 0
            log(
                f"PR #{pr_number} current-head observation uncertain "
                f"({snapshot.reason}) at {snapshot.head_ref_oid or 'unknown'}; retrying"
            )

        if now + POLL_INTERVAL_SECONDS >= deadline:
            # Continue-equivalent re-queue: exit 0 so the task reaches review;
            # the reviewer observes the bounded evidence and can hold/requeue.
            # The convergence comparison above, not this polling interval, is
            # the completeness proof.
            if snapshot.status == SnapshotStatus.VALID and pending:
                deadline_reason = "non-terminal-checks"
            elif snapshot.status == SnapshotStatus.VALID:
                deadline_reason = "terminal-candidate-not-converged"
            else:
                deadline_reason = snapshot.reason
            log(
                f"internal deadline ({DEADLINE_SECONDS // 60} minutes) reached for "
                f"PR #{pr_number}; releasing to review for hold-and-requeue "
                f"with bounded uncertainty {deadline_reason}"
            )
            emit_result(
                pr=pr_number,
                prState=pr_state,
                reason="deadline-requeue",
                **snapshot_fields(snapshot),
                uncertainty=snapshot_uncertainty(snapshot, deadline_reason),
            )
            return
        time.sleep(POLL_INTERVAL_SECONDS)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Route the Project Lead's explicit cycle decision."""

from __future__ import annotations

import sys


VALID_DECISIONS = {"continue", "complete", "blocked"}


def decide_project_cycle(payload: str) -> str:
    decision = payload.strip().lower()
    if decision not in VALID_DECISIONS:
        raise ValueError(
            "project-cycle payload must be exactly 'continue', 'complete', or 'blocked'"
        )
    return decision


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(
            "usage: decide-project-cycle.py <continue|complete|blocked>",
            file=sys.stderr,
        )
        return 2
    try:
        decision = decide_project_cycle(argv[1])
    except ValueError as error:
        print(error, file=sys.stderr)
        return 2
    print(decision)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

#!/usr/bin/env python3
"""Stage verified artifacts and a private environment for a fresh probe."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
import shutil
import sys


def artifact(value: object) -> dict:
    if not isinstance(value, dict) or set(value) - {"identity", "path", "sha256"}:
        raise ValueError("artifacts require identity, absolute path and sha256 only")
    source = Path(value.get("path", ""))
    if not source.is_absolute() or not source.is_file():
        raise ValueError("artifact path must be an existing absolute file")
    if not re.fullmatch(r"[0-9a-fA-F]{64}", str(value.get("sha256", ""))):
        raise ValueError("artifact requires an exact SHA-256")
    return value


def stage(value: dict, destination: Path) -> dict:
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(value["path"], destination)
    with destination.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    if digest.lower() != value["sha256"].lower():
        raise ValueError("staged artifact SHA-256 does not match the mission")
    return {"path": str(destination), "sha256": digest,
            "identity": value.get("identity", digest)}


def prepare(root: Path, name: str, payload: str) -> Path:
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,150}", name):
        raise ValueError("validation name must be a safe, unique directory name")
    request = json.loads(payload)
    if isinstance(request, dict):
        request.pop("preflight", None)
    allowed = {"role", "project", "mission", "criteria", "reportPath", "budget",
               "build", "fixtures", "publicDocs"}
    if not isinstance(request, dict) or set(request) - allowed:
        raise ValueError("validation payload must contain only mission fields")
    if request.get("role") not in {"customer", "engineering", "retrospective"}:
        raise ValueError("validation role must be customer, engineering, or retrospective")
    for field in ("project", "mission", "criteria", "reportPath", "budget"):
        if not request.get(field):
            raise ValueError(f"validation payload requires {field}")
    if not isinstance(request["criteria"], list) or any(
        not isinstance(c, dict) or set(c) != {"id", "rubric"} or not c["id"] or not c["rubric"]
        for c in request["criteria"]
    ):
        raise ValueError("criteria require IDs and observable rubrics")
    if not isinstance(request["budget"], dict) or any(
        request["budget"].get(key) in (None, "") for key in ("time", "download", "disk", "process", "paid")
    ):
        raise ValueError("budget requires time, download, disk, process and paid bounds")
    root = root.resolve()
    projects = (root / "docs/temp/projects").resolve()
    report = Path(request["reportPath"])
    if not report.is_absolute():
        raise ValueError("reportPath must be absolute")
    report = report.resolve()
    if not projects.is_relative_to(root) or not report.is_relative_to(projects) or report.suffix != ".md":
        raise ValueError("reportPath must be a Markdown report under docs/temp/projects")
    if report.exists():
        raise ValueError("reportPath already exists; use a new report name")
    probes = root / "docs/temp/probes"
    if not probes.resolve().is_relative_to(root):
        raise ValueError("probe root escapes workspace")
    target = probes / name
    if target.exists() or target.is_symlink() or not target.resolve().is_relative_to(probes.resolve()):
        raise ValueError("probe workspace already exists or escapes probes; use a new name")
    build = request.get("build")
    if request["role"] != "retrospective" and build is None:
        raise ValueError("customer and engineering validation require a prebuilt artifact")
    if build is not None:
        artifact(build)
        if not build.get("identity"):
            raise ValueError("build requires an immutable identity")
    for field in ("fixtures", "publicDocs"):
        if not isinstance(request.get(field, []), list):
            raise ValueError(f"{field} must be an artifact list")
        for value in request.get(field, []):
            artifact(value)
    # Atomic creation rejects repeated/concurrent admission. A failed staging
    # attempt leaves its evidence and requires a fresh validation Work name.
    target.mkdir(parents=True, exist_ok=False)
    if build is not None:
        request["build"] = stage(build, target / "bin" / Path(build["path"]).name)
    for field in ("fixtures", "publicDocs"):
        request[field] = [stage(value, target / field / str(i) / Path(value["path"]).name)
                          for i, value in enumerate(request.get(field, []))]
    environment = {}
    for key, folder in (("HOME", "profile"), ("USERPROFILE", "profile"),
                        ("XDG_CACHE_HOME", "cache"), ("XDG_CONFIG_HOME", "config"),
                        ("APPDATA", "appdata"), ("LOCALAPPDATA", "localappdata")):
        location = target / folder
        location.mkdir(exist_ok=True)
        environment[key] = str(location)
    request["environment"] = environment
    request["reportPath"] = str(report)
    (target / "mission.json").write_text(json.dumps(request, indent=2) + "\n", encoding="utf-8")
    report.parent.mkdir(parents=True, exist_ok=True)
    return target


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: prepare-validation.py <name> <payload-json>", file=sys.stderr)
        return 2
    try:
        # This repository factory is nested under <repository>/factory/scripts.
        # Project contracts and probe directories belong to that repository,
        # independent of the runtime invocation working directory.
        prepare(Path(__file__).resolve().parents[2], sys.argv[1], sys.argv[2])
    except (ValueError, OSError, TypeError) as error:
        print(f"validation admission failed: {error}", file=sys.stderr)
        return 2
    print("validation workspace ready")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Reconcile waiting Project Leads without creating overlapping cycles.

The script is intended for a SCRIPT_RUN workstation.  It reads the selected
Factory Session through the public ``you`` CLI, then makes only deliberate,
idempotent moves of stranded existing ``project`` Work from ``waiting`` to
``init``.  Blocked Projects are inspect-only. It never submits a new Project
or cycle.

Usage:
    python3 factory/scripts/reconcile-projects.py --session SESSION_ID

The worker workstation should pass ``--session {{ .Context.SessionID }}`` and
may override ``--server`` when the Factory host is not on the local default
port.  ``--dry-run`` is useful for local probes and tests.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import subprocess
import sys
from typing import Any, Callable, Iterable, Mapping, Optional


DEFAULT_SERVER = "http://127.0.0.1:7437"
CLI_TIMEOUT_SECONDS = 30
CHILD_WORK_TYPES = frozenset({"idea", "plan", "task", "review", "validation"})
ACTIVE_WORKER_SESSION_STATES = frozenset({"RESERVED", "STARTING", "RUNNING", "PAUSED"})
NONTERMINAL_STATE_TYPES = frozenset({"INITIAL", "PROCESSING"})
REQUEST_ID_LIMIT = 180


class ReconcileError(RuntimeError):
    """A public CLI read or move failed before reconciliation could finish."""


CommandRunner = Callable[[list[str]], subprocess.CompletedProcess[str]]


def _work_id(work: Mapping[str, Any]) -> str:
    return _string(work.get("workId") or work.get("id"))


def _work_name(work: Mapping[str, Any]) -> str:
    return _string(work.get("name"))


def _work_type(work: Mapping[str, Any]) -> str:
    return _string(work.get("workTypeName") or work.get("workType"))


def _state(work: Mapping[str, Any]) -> tuple[str, str]:
    state = work.get("state")
    if not isinstance(state, Mapping):
        return "", ""
    return _string(state.get("name")), _string(state.get("type")).upper()


def _string(value: Any) -> str:
    return value.strip() if isinstance(value, str) else ""


def _payload_object(work: Mapping[str, Any]) -> Mapping[str, Any]:
    payload = work.get("payload")
    if isinstance(payload, Mapping):
        return payload
    if isinstance(payload, str):
        try:
            decoded = json.loads(payload)
        except json.JSONDecodeError:
            return {}
        return decoded if isinstance(decoded, Mapping) else {}
    return {}


def _run_command(command: list[str]) -> subprocess.CompletedProcess[str]:
    try:
        return subprocess.run(
            command,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=CLI_TIMEOUT_SECONDS,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        raise ReconcileError(f"could not execute {' '.join(command[:2])}: {error}") from error


def _cli_json(
    runner: CommandRunner,
    server: str,
    *arguments: str,
) -> Any:
    command = ["you", "--server", server, "--json", *arguments]
    result = runner(command)
    if result.returncode != 0:
        details = (result.stderr or result.stdout or "").strip()
        if len(details) > 400:
            details = details[:400] + "..."
        raise ReconcileError(
            f"{' '.join(command)} failed with exit {result.returncode}"
            + (f": {details}" if details else "")
        )
    try:
        return json.loads(result.stdout or "")
    except json.JSONDecodeError as error:
        raise ReconcileError(
            f"{' '.join(command)} returned invalid JSON"
        ) from error


def _session_is_running(session: Any) -> bool:
    if not isinstance(session, Mapping):
        raise ReconcileError("session show returned a non-object JSON value")
    runtime = session.get("runtime")
    if not isinstance(runtime, Mapping):
        raise ReconcileError("session show omitted runtime")
    progress = runtime.get("progress")
    if not isinstance(progress, Mapping):
        raise ReconcileError("session show omitted runtime.progress")
    # Factory state is the authoritative scheduler lifecycle.  Runtime status
    # is IDLE while a healthy server has no dispatch in flight, so it must not
    # be used as the sole liveness test.
    return _string(progress.get("factoryState")).upper() == "RUNNING"


def _work_results(response: Any) -> list[Mapping[str, Any]]:
    if not isinstance(response, Mapping):
        raise ReconcileError("work list returned a non-object JSON value")
    results = response.get("results")
    if results is None:
        return []
    if not isinstance(results, list) or any(not isinstance(item, Mapping) for item in results):
        raise ReconcileError("work list returned an invalid results array")
    return list(results)


def _worker_session_results(response: Any) -> list[Mapping[str, Any]]:
    if not isinstance(response, Mapping):
        raise ReconcileError("Worker Session list returned a non-object JSON value")
    sessions = response.get("sessions")
    if sessions is None:
        return []
    if not isinstance(sessions, list) or any(not isinstance(item, Mapping) for item in sessions):
        raise ReconcileError("Worker Session list returned an invalid sessions array")
    return list(sessions)


def _session_has_active_work(
    sessions: Iterable[Mapping[str, Any]], work_id: str, session_id: str
) -> bool:
    for session in sessions:
        observed_session_id = _string(session.get("factorySessionId"))
        if observed_session_id and observed_session_id != session_id:
            continue
        if _string(session.get("state")).upper() not in ACTIVE_WORKER_SESSION_STATES:
            continue
        ids = set()
        candidate = session.get("workId")
        if isinstance(candidate, str):
            ids.add(candidate)
        candidates = session.get("workIds")
        if isinstance(candidates, list):
            ids.update(item for item in candidates if isinstance(item, str))
        # The Work-scoped endpoint may omit nullable Work identity fields. An
        # active observation with no identity is still potentially this lead;
        # fail closed rather than dispatching concurrently.
        if not ids:
            return True
        if work_id in ids:
            return True
    return False


def _belongs_to_project(work: Mapping[str, Any], project: Mapping[str, Any]) -> bool:
    name = _work_name(work)
    project_name = _work_name(project)
    if not name or not project_name or _work_type(work) not in CHILD_WORK_TYPES:
        return False

    project_payload = _payload_object(project)
    child_payload = _payload_object(work)
    project_root = _string(project_payload.get("projectRoot"))
    if _string(child_payload.get("project")) == project_name:
        return True
    if project_root and _string(child_payload.get("projectRoot")) == project_root:
        return True

    # Project Lead's documented naming contract is PROJECT-cNN-... for ideas;
    # plan/task/review/validation Work keeps that authored name through the
    # delivery graph.
    return name.startswith(project_name + "-c")


def _project_children(
    works: Iterable[Mapping[str, Any]], project: Mapping[str, Any]
) -> list[Mapping[str, Any]]:
    return [work for work in works if _belongs_to_project(work, project)]


def _same_name_cycles(
    works: Iterable[Mapping[str, Any]], project_name: str
) -> list[Mapping[str, Any]]:
    return [
        work
        for work in works
        if _work_type(work) == "project-cycle" and _work_name(work) == project_name
    ]


def _observation_view(work: Mapping[str, Any]) -> dict[str, Any]:
    """Keep the request fingerprint bounded to public, state-bearing fields."""
    failure = work.get("failureDetail")
    if isinstance(failure, Mapping):
        failure = {
            "reason": _string(failure.get("reason")),
            "message": _string(failure.get("message"))[:512],
        }
    else:
        failure = None
    return {
        "workId": _work_id(work),
        "name": _work_name(work),
        "workTypeName": _work_type(work),
        "state": work.get("state"),
        "currentChainingTraceId": work.get("currentChainingTraceId"),
        "confirmationState": work.get("confirmationState"),
        "failureDetail": failure,
    }


def _observation_revision(
    project: Mapping[str, Any],
    children: Iterable[Mapping[str, Any]],
    cycles: Iterable[Mapping[str, Any]],
    reason: str,
) -> str:
    view = {
        "project": _observation_view(project),
        "children": sorted(
            (_observation_view(child) for child in children),
            key=lambda item: (item["workId"], item["name"]),
        ),
        "cycles": sorted(
            (_observation_view(cycle) for cycle in cycles),
            key=lambda item: (item["workId"], item["name"]),
        ),
        "reason": reason,
    }
    encoded = json.dumps(view, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:20]


def _request_id(work_id: str, observation_revision: str) -> str:
    value = re.sub(r"[^A-Za-z0-9_.-]+", "-", work_id).strip("-.")
    value = value or "unknown-project"
    return ("project-reconcile-" + value + "-" + observation_revision)[:REQUEST_ID_LIMIT]


def _move_project(
    runner: CommandRunner,
    server: str,
    session_id: str,
    project: Mapping[str, Any],
    observation_revision: str,
) -> None:
    work_id = _work_id(project)
    if not work_id:
        raise ReconcileError(f"project { _work_name(project)!r } has no workId")
    _cli_json(
        runner,
        server,
        "work",
        "move",
        work_id,
        "init",
        "--session",
        session_id,
        "--request-id",
        _request_id(work_id, observation_revision),
    )


def reconcile(
    *,
    server: str,
    session_id: str,
    dry_run: bool = False,
    runner: CommandRunner = _run_command,
) -> dict[str, Any]:
    """Inspect one session and return a deterministic reconciliation summary."""
    session_id = session_id.strip()
    server = server.strip()
    if not session_id:
        raise ReconcileError("session id is required")
    if not server:
        raise ReconcileError("server is required")
    session = _cli_json(runner, server, "session", "show", session_id)
    if not _session_is_running(session):
        return {
            "sessionId": session_id,
            "server": server,
            "status": "skipped",
            "reason": "factory-not-running",
            "moved": [],
            "skipped": [],
        }

    works = _work_results(
        _cli_json(
            runner,
            server,
            "work",
            "list",
            "--session",
            session_id,
        )
    )
    projects = [work for work in works if _work_type(work) == "project"]
    grouped: dict[str, list[Mapping[str, Any]]] = {}
    for project in projects:
        grouped.setdefault(_work_name(project), []).append(project)

    moved: list[dict[str, Any]] = []
    skipped: list[dict[str, str]] = []
    for project_name in sorted(grouped):
        candidates = grouped[project_name]
        if not project_name:
            skipped.append({"reason": "project-without-name"})
            continue
        if len(candidates) != 1:
            skipped.append({"name": project_name, "reason": "ambiguous-project-name"})
            continue
        project = candidates[0]
        state_name, _ = _state(project)
        if state_name not in {"waiting", "blocked"}:
            continue
        if state_name == "blocked":
            skipped.append({"name": project_name, "reason": "blocked-inspect-only"})
            continue

        children = _project_children(works, project)
        project_id = _work_id(project)
        if not project_id:
            skipped.append({"name": project_name, "reason": "project-without-work-id"})
            continue

        cycles = _same_name_cycles(works, project_name)
        # A cycle of any state is left to the authored graph. Moving the
        # project while that cycle remains visible can race its completion
        # transition and create overlapping same-name cycles.
        if cycles:
            reason = "cycle-in-progress" if any(
                _state(cycle)[1] in NONTERMINAL_STATE_TYPES for cycle in cycles
            ) else "cycle-transition-pending"
            skipped.append({"name": project_name, "reason": reason})
            continue

        # With no visible cycle, a waiting lead is structurally stranded. This
        # is the public-state staleness signal; no filesystem clock is used.
        reason = "missing-cycle"

        worker_sessions = _worker_session_results(
            _cli_json(
                runner,
                server,
                "worker-sessions",
                "list",
                "--work-id",
                project_id,
                "--session",
                session_id,
            )
        )
        if _session_has_active_work(worker_sessions, project_id, session_id):
            skipped.append({"name": project_name, "reason": "project-lead-active"})
            continue

        observation_revision = _observation_revision(
            project, children, cycles, reason
        )
        unfinished_children = [
            _work_id(child)
            for child in children
            if _state(child)[1] in NONTERMINAL_STATE_TYPES
        ]
        detail: dict[str, Any] = {
            "name": project_name,
            "workId": project_id,
            "reason": reason,
            "observationRevision": observation_revision,
        }
        if unfinished_children:
            detail["unfinishedChildren"] = unfinished_children
        if dry_run:
            moved.append(detail)
            continue
        _move_project(runner, server, session_id, project, observation_revision)
        moved.append(detail)

    return {
        "sessionId": session_id,
        "server": server,
        "status": "dry-run" if dry_run else "completed",
        "moved": moved,
        "skipped": skipped,
    }


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--server", default=DEFAULT_SERVER)
    parser.add_argument("--session", required=True)
    parser.add_argument("--dry-run", action="store_true")
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    args = _parser().parse_args(argv)
    try:
        result = reconcile(
            server=args.server,
            session_id=args.session,
            dry_run=args.dry_run,
        )
    except ReconcileError as error:
        print(f"project reconciliation failed: {error}", file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""setup-workspace.py — Create or reuse a git worktree for a PRD.

Usage: python scripts/agents/setup-workspace.py <prd-name>

Reads the exact tasks/todo/<prd-name>.json packet from the main checkout or a
Git-registered worktree, uses <prd-name> as the branch/worktree name, syncs
main, creates or reuses a git worktree, copies the PRD (and optional .md) into
the worktree root, and prints a JSON result to stdout.

Exit 0 on success (stdout = JSON blob), exit 1 on failure (stderr = stage-specific error).
"""

import contextlib
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import threading
import time
from pathlib import Path


IMMUTABLE_OBJECT_ID = re.compile(r"^(?:[0-9a-f]{40}|[0-9a-f]{64})$")
SNAPSHOT_REF_PREFIX = "refs/factory-snapshots/"
ROOT_SYNC_LOCK_FILENAME = "setup-workspace-root-sync.lock"
MAX_ANCESTOR_RESIDUE_PATHS = 20
MAX_DIRTY_ROOT_SAMPLE_ENTRIES = 12
MAX_DIRTY_ROOT_ATTRIBUTION_PATHS = 5
MAX_DIRTY_ROOT_ATTRIBUTION_WORKTREES = 20
MAX_CANDIDATE_DIAGNOSTIC_PATHS = 8
MAX_CANDIDATE_DIAGNOSTIC_PATH_LENGTH = 240
MAX_STATUS_FAILURE_DETAILS = 512
MAX_FAILURE_DETAILS = 1024
MAX_DISPLAYED_STATUS_PATH_LENGTH = 240
FILE_DIGEST_CHUNK_SIZE = 1024 * 1024
WINDOWS_RESERVED_PATH_COMPONENT = re.compile(
    r"(?<![a-z0-9])(?:nul|con|prn|aux|com[1-9]|lpt[1-9])"
    r"(?:\.[^\\/:*?\"<>|\r\n]*)?(?![a-z0-9])",
    re.IGNORECASE,
)
_ROOT_SYNC_THREAD_LOCKS = {}
_ROOT_SYNC_THREAD_LOCKS_GUARD = threading.Lock()
_MISSING_PATH = object()
_UNAVAILABLE_PATH = object()


class DirtyRootError(RuntimeError):
    """A bounded, already-rendered diagnostic for an operator-owned root."""


class RootStatusError(RuntimeError):
    """A root status inspection failure that belongs to the setup preflight."""


class RootSyncResult(str):
    """Describe root synchronization and its optional fresh remote baseline."""

    def __new__(cls, message, fresh_origin_main_sha=None):
        result = super().__new__(cls, message)
        result.fresh_origin_main_sha = fresh_origin_main_sha
        return result


def raw_failure_details(error):
    """Return an exception's text without allowing rendering to raise again."""
    try:
        return str(error).strip()
    except Exception as render_error:  # noqa: BLE001 - defensive boundary
        return (
            f"{type(error).__name__} details could not be rendered: "
            f"{type(render_error).__name__}"
        )


def bounded_failure_details(value, limit=MAX_FAILURE_DETAILS):
    """Safely render and bound command or exception details for the terminal."""
    details = (
        raw_failure_details(value)
        if not isinstance(value, str)
        else value.strip()
    )
    rendered = []
    for character in details:
        codepoint = ord(character)
        if character == "\n":
            rendered.append("\n")
        elif character == "\t":
            rendered.append("\\t")
        elif character == "\r":
            rendered.append("\\r")
        elif (
            codepoint < 0x20
            or codepoint == 0x7F
            or 0xD800 <= codepoint <= 0xDFFF
        ):
            rendered.append(f"\\u{codepoint:04x}")
        else:
            rendered.append(character)

    result = "".join(rendered)
    if len(result) <= limit:
        return result
    omitted = len(result) - limit
    suffix = f"... ({omitted} more characters)"
    return f"{result[: max(0, limit - len(suffix))]}{suffix}"


def is_platform_invalid_path_failure(details):
    """Recognize Git and Windows messages for paths unavailable to the host."""
    lowered = details.casefold()
    if "\x00" in lowered or "\\u0000" in lowered:
        return True
    if "invalid path" in lowered or "invalid filename" in lowered:
        return True
    if "path" in lowered and "invalid" in lowered:
        return True

    has_reserved_component = bool(WINDOWS_RESERVED_PATH_COMPONENT.search(details))
    if not has_reserved_component:
        return False
    return any(
        marker in lowered
        for marker in (
            "not allowed",
            "not valid",
            "cannot create",
            "could not create",
            "checkout",
            "worktree",
            "windows",
            "win32",
        )
    )


def format_stage_failure(stage, error):
    """Render bounded, actionable failure text while preserving the stage."""
    raw_details = raw_failure_details(error)
    details = bounded_failure_details(raw_details)
    if not details:
        details = f"unexpected {type(error).__name__} without additional details"

    if is_platform_invalid_path_failure(raw_details):
        return (
            f"{stage}: Git rejected a Windows-reserved or otherwise "
            "platform-invalid path (for example, the literal NUL device name). "
            "Inspect the reported path, manually back up any needed content, "
            "then remove or rename that path before retrying; setup-workspace "
            f"does not modify it automatically. Details: {details}"
        )
    return f"{stage}: {details}"


def run_git(*args, cwd=None, check=True, env=None):
    """Run a git command, returning stdout. Raises on failure if check=True."""
    result = subprocess.run(
        ["git"] + list(args),
        cwd=cwd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="surrogateescape",
        env=env,
    )
    if check and result.returncode != 0:
        raise RuntimeError(
            f"git {bounded_failure_details(' '.join(args))} failed "
            f"(exit {result.returncode}): "
            f"{command_failure_details(result)}"
        )
    return result


def get_repo_root():
    """Discover the repository root via git."""
    result = run_git("rev-parse", "--show-toplevel")
    return Path(result.stdout.strip())


def current_branch(repo_path):
    """Return the currently checked-out branch name, or empty when detached."""
    return run_git(
        "branch", "--show-current", cwd=repo_path, check=False,
    ).stdout.strip()


def working_tree_has_local_changes(repo_path):
    """True when the working tree has staged, unstaged, or untracked changes."""
    status = run_git("status", "--porcelain", cwd=repo_path, check=False)
    return bool(status.stdout.strip())


def truncate_status_details(details):
    """Keep status-command failures useful without emitting unbounded output."""
    return bounded_failure_details(details, MAX_STATUS_FAILURE_DETAILS)


def parse_porcelain_status(output):
    """Parse NUL-delimited porcelain-v1 status entries safely."""
    entries = []
    tokens = output.split("\0")
    token_index = 0
    while token_index < len(tokens):
        token = tokens[token_index]
        token_index += 1
        if not token:
            continue
        if len(token) < 4 or token[2] != " ":
            raise RuntimeError(
                "git status returned malformed porcelain output"
            )

        status = token[:2]
        paths = [token[3:]]
        if "R" in status or "C" in status:
            if token_index >= len(tokens) or not tokens[token_index]:
                raise RuntimeError(
                    "git status returned an incomplete rename or copy entry"
                )
            paths.append(tokens[token_index])
            token_index += 1
        entries.append({"status": status, "paths": tuple(paths)})

    return entries


def repository_status_entries(repo_path):
    """Return non-ignored root status entries, or raise a bounded failure."""
    try:
        result = run_git(
            "status",
            "--porcelain=v1",
            "-z",
            "--untracked-files=all",
            cwd=repo_path,
            check=False,
        )
    except OSError as error:
        raise RuntimeError(f"could not run git status: {error}") from error

    if result.returncode != 0:
        details = truncate_status_details(command_failure_details(result))
        raise RuntimeError(
            "git status --porcelain=v1 failed "
            f"(exit {result.returncode}): {details}"
        )

    try:
        return parse_porcelain_status(result.stdout)
    except RuntimeError as error:
        raise RuntimeError(f"could not inspect repository status: {error}") from error


def status_entry_kind(entry):
    """Return the operator-facing category for one porcelain status entry."""
    return "untracked" if entry["status"] == "??" else "tracked"


def status_entry_sort_key(entry):
    """Return a stable sort key independent of Git's presentation order."""
    kind_order = 0 if status_entry_kind(entry) == "tracked" else 1
    return kind_order, entry["paths"], entry["status"]


def status_entry_path(entry):
    """Render one status path as a safely escaped, bounded display value."""
    paths = entry["paths"]
    if "R" in entry["status"] or "C" in entry["status"]:
        paths = tuple(reversed(paths))

    rendered_paths = []
    for path in paths:
        if len(path) > MAX_DISPLAYED_STATUS_PATH_LENGTH:
            path = (
                path[: MAX_DISPLAYED_STATUS_PATH_LENGTH - 1]
                + "…"
            )
        rendered_paths.append(json.dumps(path, ensure_ascii=True))
    return " -> ".join(rendered_paths)


def dirty_root_sample(entries):
    """Select a stable bounded sample while retaining both status categories."""
    grouped = {
        "tracked": sorted(
            (entry for entry in entries if status_entry_kind(entry) == "tracked"),
            key=status_entry_sort_key,
        ),
        "untracked": sorted(
            (entry for entry in entries if status_entry_kind(entry) == "untracked"),
            key=status_entry_sort_key,
        ),
    }

    sample = [group[0] for group in grouped.values() if group]
    remaining = [
        entry
        for entry in entries
        if all(entry is not selected for selected in sample)
    ]
    remaining.sort(key=status_entry_sort_key)
    sample.extend(remaining[: max(0, MAX_DIRTY_ROOT_SAMPLE_ENTRIES - len(sample))])
    sample.sort(key=status_entry_sort_key)
    return sample


def path_content_digest(path):
    """Return a bounded-memory digest for a file, or a path-state sentinel."""
    try:
        if not path.exists():
            return _MISSING_PATH
        if not path.is_file():
            return _UNAVAILABLE_PATH

        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(
                lambda: stream.read(FILE_DIGEST_CHUNK_SIZE),
                b"",
            ):
                digest.update(chunk)
        return digest.digest()
    except (OSError, ValueError):
        return _UNAVAILABLE_PATH


def git_revision_path_digest(repo_path, revision, relative_path):
    """Return a digest for a revision path without mutating the repository."""
    try:
        result = run_git(
            "show",
            f"{revision}:{relative_path}",
            cwd=repo_path,
            check=False,
        )
    except Exception:  # noqa: BLE001 - attribution must never replace refusal
        return _UNAVAILABLE_PATH

    if result.returncode != 0:
        return _MISSING_PATH
    try:
        contents = result.stdout.encode("utf-8", "surrogateescape")
    except (AttributeError, UnicodeEncodeError):
        return _UNAVAILABLE_PATH
    return hashlib.sha256(contents).digest()


def dirty_root_attribution_fingerprints(repo_path, entries):
    """Capture at most five root changes relative to the fetched baseline."""
    try:
        if not origin_main_ref_exists(repo_path):
            return []

        fingerprints = []
        for entry in dirty_root_sample(entries)[:MAX_DIRTY_ROOT_ATTRIBUTION_PATHS]:
            paths = entry.get("paths", ())
            if not paths:
                continue
            relative_path = paths[0]
            baseline = git_revision_path_digest(
                repo_path,
                "refs/remotes/origin/main",
                relative_path,
            )
            if baseline is _UNAVAILABLE_PATH:
                continue

            current = path_content_digest(repo_path / relative_path)
            if current is _UNAVAILABLE_PATH or current == baseline:
                continue
            fingerprints.append((relative_path, baseline, current))
        return fingerprints
    except Exception:  # noqa: BLE001 - attribution is best effort only
        return []


def sibling_worktree_candidates(repo_path):
    """Return a deterministic, bounded list of sibling directories."""
    worktrees_dir = repo_path / ".claude" / "worktrees"
    try:
        children = sorted(
            worktrees_dir.iterdir(),
            key=lambda path: os.fsencode(path.name),
        )
    except (OSError, UnicodeError, ValueError):
        return []

    candidates = []
    for candidate in children:
        try:
            if not candidate.is_dir():
                continue
        except OSError:
            continue
        candidates.append(candidate)
        if len(candidates) >= MAX_DIRTY_ROOT_ATTRIBUTION_WORKTREES:
            break
    return candidates


def is_valid_sibling_worktree(candidate):
    """Check one sibling independently so stale entries cannot abort refusal."""
    try:
        result = run_git(
            "rev-parse",
            "--show-toplevel",
            cwd=candidate,
            check=False,
        )
        if result.returncode != 0 or not result.stdout.strip():
            return False
        return Path(result.stdout.strip()).resolve() == candidate.resolve()
    except Exception:  # noqa: BLE001 - one broken candidate is non-fatal
        return False


def dirty_root_sibling_attribution(repo_path, entries):
    """Find bounded sibling worktrees carrying the same sampled root changes."""
    fingerprints = dirty_root_attribution_fingerprints(repo_path, entries)
    if not fingerprints:
        return []

    matches = []
    for candidate in sibling_worktree_candidates(repo_path):
        if not is_valid_sibling_worktree(candidate):
            continue

        matching_paths = []
        for relative_path, baseline, current in fingerprints:
            sibling_current = path_content_digest(candidate / relative_path)
            if sibling_current is _UNAVAILABLE_PATH:
                continue
            if sibling_current == current and sibling_current != baseline:
                matching_paths.append(relative_path)
        if matching_paths:
            matches.append((candidate.name, matching_paths))

    if not matches:
        return []

    lines = [
        "likely sibling worktree matches (same changes relative to origin/main):",
    ]
    for candidate_name, matching_paths in matches:
        rendered_paths = ", ".join(
            json.dumps(path, ensure_ascii=True)
            for path in matching_paths
        )
        lines.append(
            "  sibling worktree "
            f"{json.dumps(candidate_name, ensure_ascii=True)} "
            f"matches path(s): {rendered_paths}"
        )
    return lines


def dirty_root_diagnostic(repo_path, entries):
    """Describe dirty-root evidence and safe manual recovery guidance."""
    tracked_count = sum(
        status_entry_kind(entry) == "tracked" for entry in entries
    )
    untracked_count = len(entries) - tracked_count
    sample = dirty_root_sample(entries)
    omitted_count = len(entries) - len(sample)

    lines = [
        f"repository root is dirty: {repo_path}",
        "status counts: "
        f"total entries={len(entries)}; "
        f"tracked changes={tracked_count}; "
        f"untracked files={untracked_count}",
        "workspace setup stopped before root synchronization, snapshot "
        "capture, worktree preparation, pruning, or PRD copy",
        f"status sample (up to {MAX_DIRTY_ROOT_SAMPLE_ENTRIES} entries):",
    ]

    for kind in ("tracked", "untracked"):
        lines.append(f"  {kind}:")
        category_sample = [
            entry for entry in sample if status_entry_kind(entry) == kind
        ]
        if not category_sample:
            lines.append("    (none)")
            continue
        for entry in category_sample:
            lines.append(
                f"    {entry['status']} {status_entry_path(entry)}"
            )

    if omitted_count:
        lines.append(
            f"  {omitted_count} additional path(s) omitted from the sample"
        )
    lines.append(
        "Inspect the repository root manually, then commit the changes or "
        "back them up and restore them manually before retrying."
    )
    lines.extend(dirty_root_sibling_attribution(repo_path, entries))
    return "\n".join(lines)


def root_status_for_setup(repo_root):
    """Inspect root dirt after fetch while preserving the preflight failure stage."""
    try:
        return repository_status_entries(repo_root)
    except Exception as error:  # noqa: BLE001 - preserve the CLI stage boundary
        raise RootStatusError(str(error)) from error


def command_failure_details(result):
    """Return useful stderr/stdout text from a failed git command."""
    return (
        bounded_failure_details(result.stderr or result.stdout)
        or "no details available"
    )


def require_git_output(result, description):
    """Return non-empty command output or raise a contextual error."""
    if result.returncode != 0:
        raise RuntimeError(f"{description}: {command_failure_details(result)}")
    output = result.stdout.strip()
    if not output:
        raise RuntimeError(f"{description}: git returned no object identifier")
    return output


def immutable_object_id(value):
    """Return True only for a complete SHA-1 or SHA-256 object identifier."""
    return bool(IMMUTABLE_OBJECT_ID.fullmatch(value))


def snapshot_ref_name(snapshot_id):
    """Return the private recovery ref for an immutable snapshot ID."""
    return f"{SNAPSHOT_REF_PREFIX}{snapshot_id}"


def anchor_snapshot(repo_path, snapshot_id):
    """Keep a captured snapshot reachable without touching the stash stack."""
    ref_name = snapshot_ref_name(snapshot_id)
    result = run_git(
        "update-ref", ref_name, snapshot_id, "",
        cwd=repo_path, check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"failed to anchor snapshot {snapshot_id} at {ref_name}: "
            f"{command_failure_details(result)}"
        )


def remove_snapshot_anchor(repo_path, snapshot_id, scope_label):
    """Delete only the expected private ref after a successful restore."""
    ref_name = snapshot_ref_name(snapshot_id)
    result = run_git(
        "update-ref", "-d", ref_name, snapshot_id,
        cwd=repo_path, check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"{scope_label} sync restored snapshot {snapshot_id}, but could "
            f"not remove its private recovery ref {ref_name}; the snapshot "
            f"remains anchored: {command_failure_details(result)}"
        )


def root_sync_lock_path(repo_path):
    """Return the persistent lock path shared by root-sync invocations."""
    common_dir = require_git_output(
        run_git(
            "rev-parse", "--git-common-dir", cwd=repo_path, check=False,
        ),
        "failed to resolve Git common directory for root sync lock",
    )
    common_path = Path(common_dir)
    if not common_path.is_absolute():
        common_path = Path(repo_path) / common_path
    return common_path.resolve() / ROOT_SYNC_LOCK_FILENAME


def root_sync_thread_lock(lock_path):
    """Return the in-process lock for one repository's root sync path."""
    lock_key = os.path.normcase(str(lock_path))
    with _ROOT_SYNC_THREAD_LOCKS_GUARD:
        return _ROOT_SYNC_THREAD_LOCKS.setdefault(lock_key, threading.Lock())


@contextlib.contextmanager
def root_sync_lock(repo_path):
    """Own root synchronization across threads and setup-workspace processes."""
    lock_path = root_sync_lock_path(repo_path)
    thread_lock = root_sync_thread_lock(lock_path)
    with thread_lock:
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        with lock_path.open("a+b") as lock_file:
            lock_file.seek(0, os.SEEK_END)
            if lock_file.tell() == 0:
                lock_file.write(b"\0")
                lock_file.flush()

            if os.name == "nt":
                import msvcrt

                while True:
                    lock_file.seek(0)
                    try:
                        msvcrt.locking(lock_file.fileno(), msvcrt.LK_NBLCK, 1)
                        break
                    except OSError:
                        time.sleep(0.05)
            else:
                import fcntl

                fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)

            try:
                yield
            finally:
                if os.name == "nt":
                    import msvcrt

                    lock_file.seek(0)
                    msvcrt.locking(lock_file.fileno(), msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl

                    fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)


def temporary_index_path():
    """Create a path for a temporary Git index without leaving an empty file."""
    file_descriptor, path = tempfile.mkstemp(prefix="setup-workspace-index-")
    os.close(file_descriptor)
    temporary_path = Path(path)
    temporary_path.unlink()
    return temporary_path


def git_index_path(repo_path):
    """Resolve the worktree-specific index path used by Git."""
    result = run_git("rev-parse", "--git-path", "index", cwd=repo_path)
    index_path = Path(result.stdout.strip())
    if not index_path.is_absolute():
        index_path = repo_path / index_path
    return index_path


def environment_with_index(index_path):
    """Return an environment that directs Git commands to index_path."""
    environment = os.environ.copy()
    environment["GIT_INDEX_FILE"] = str(index_path)
    return environment


def working_tree_tree(repo_path):
    """Write the tracked working-tree state to an immutable tree object."""
    temporary_path = temporary_index_path()
    try:
        source_index = git_index_path(repo_path)
        if source_index.exists():
            shutil.copy2(source_index, temporary_path)
        else:
            run_git(
                "read-tree", "HEAD", cwd=repo_path,
                env=environment_with_index(temporary_path),
            )

        environment = environment_with_index(temporary_path)
        run_git("add", "-u", cwd=repo_path, env=environment)
        return require_git_output(
            run_git("write-tree", cwd=repo_path, env=environment),
            "failed to capture the tracked working tree",
        )
    finally:
        temporary_path.unlink(missing_ok=True)


def untracked_paths(repo_path):
    """Return non-ignored untracked paths as Git pathspec arguments."""
    result = run_git(
        "ls-files", "--others", "--exclude-standard", "-z",
        cwd=repo_path,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"failed to enumerate untracked files: {command_failure_details(result)}"
        )
    return [path for path in result.stdout.split("\0") if path]


def untracked_tree(repo_path, paths):
    """Write the captured untracked files to an immutable tree object."""
    temporary_path = temporary_index_path()
    try:
        environment = environment_with_index(temporary_path)
        run_git("read-tree", "--empty", cwd=repo_path, env=environment)
        run_git("add", "--", *paths, cwd=repo_path, env=environment)
        return require_git_output(
            run_git("write-tree", cwd=repo_path, env=environment),
            "failed to capture untracked files",
        )
    finally:
        temporary_path.unlink(missing_ok=True)


def commit_tree(repo_path, tree, parents, message):
    """Create a dangling commit that owns one part of a local snapshot."""
    args = ["commit-tree", tree]
    for parent in parents:
        args.extend(["-p", parent])
    args.extend(["-m", message])
    object_id = require_git_output(
        run_git(*args, cwd=repo_path, check=False),
        f"failed to create snapshot object for {message}",
    )
    if not immutable_object_id(object_id):
        raise RuntimeError(
            f"failed to create snapshot object for {message}: "
            f"invalid object identifier {object_id!r}"
        )
    return object_id


def clear_local_changes(repo_path, snapshot_id):
    """Remove the captured state from the worktree before synchronization."""
    for args in (("reset", "--hard", "HEAD"), ("clean", "-fd")):
        result = run_git(*args, cwd=repo_path, check=False)
        if result.returncode != 0:
            raise RuntimeError(
                f"failed to clear local changes for snapshot {snapshot_id}: "
                f"{command_failure_details(result)}"
            )


def stash_local_changes(repo_path, label):
    """Capture local changes in a stack-independent commit snapshot.

    The snapshot has a working-tree commit, an index commit, and, when needed,
    an untracked-files commit as its third parent. It is never added to the
    shared refs/stash stack, so its complete object ID remains stable while
    other worktrees create ordinary stashes. A private recovery ref keeps the
    snapshot reachable until restoration succeeds.
    """
    if not working_tree_has_local_changes(repo_path):
        return None

    try:
        head = require_git_output(
            run_git("rev-parse", "HEAD", cwd=repo_path, check=False),
            "failed to resolve HEAD while capturing local changes",
        )
        index_tree = require_git_output(
            run_git("write-tree", cwd=repo_path, check=False),
            "failed to capture the staged index",
        )
        index_commit = commit_tree(
            repo_path,
            index_tree,
            [head],
            f"index for {label}",
        )
        tracked_tree = working_tree_tree(repo_path)
        paths = untracked_paths(repo_path)
        parents = [head, index_commit]
        if paths:
            untracked_commit = commit_tree(
                repo_path,
                untracked_tree(repo_path, paths),
                [],
                f"untracked files for {label}",
            )
            parents.append(untracked_commit)
        snapshot_id = commit_tree(repo_path, tracked_tree, parents, label)
        anchor_snapshot(repo_path, snapshot_id)
    except (OSError, RuntimeError) as error:
        raise RuntimeError(
            f"failed to capture local changes as snapshot: {error}"
        ) from error

    try:
        clear_local_changes(repo_path, snapshot_id)
    except RuntimeError as error:
        raise RuntimeError(
            f"failed to prepare synchronization with snapshot {snapshot_id}: {error}"
        ) from error

    return snapshot_id


def verify_snapshot(repo_path, snapshot_id, scope_label):
    """Verify that snapshot_id is a complete commit object before applying it."""
    if not immutable_object_id(snapshot_id):
        raise RuntimeError(
            f"{scope_label} sync could not verify snapshot {snapshot_id}: "
            "the identifier is not a complete immutable object ID"
        )

    result = run_git(
        "cat-file", "-e", f"{snapshot_id}^{{commit}}",
        cwd=repo_path,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"{scope_label} sync could not verify snapshot {snapshot_id}: "
            f"{command_failure_details(result)}"
        )


def restore_stashed_changes(repo_path, snapshot_id, scope_label):
    """Restore a snapshot by object ID and preserve its recovery ref on failure."""
    if snapshot_id is None:
        return

    verify_snapshot(repo_path, snapshot_id, scope_label)
    apply_result = run_git(
        "stash", "apply", "--index", snapshot_id,
        cwd=repo_path, check=False,
    )
    if apply_result.returncode != 0:
        fallback_result = run_git(
            "stash", "apply", snapshot_id,
            cwd=repo_path, check=False,
        )
        if fallback_result.returncode != 0:
            details = command_failure_details(fallback_result)
            if details == "no details available":
                details = command_failure_details(apply_result)
            # A failed apply leaves a half-applied, possibly conflicted tree.
            # Unmerged index entries make every later snapshot capture fail,
            # which wedges all future workspace setups until a human cleans
            # the root checkout. Reset back to a clean tree; the snapshot
            # object still holds the full residue. `git clean` honors
            # .gitignore, so ignored operator files (docs/temp, tasks/todo)
            # are untouched.
            cleanup_details = []
            for args in (("reset", "--hard", "HEAD"), ("clean", "-fd")):
                cleanup_result = run_git(*args, cwd=repo_path, check=False)
                if cleanup_result.returncode != 0:
                    cleanup_details.append(command_failure_details(cleanup_result))
            if cleanup_details:
                details = f"{details}; cleanup also failed: {'; '.join(cleanup_details)}"
            raise RuntimeError(
                f"{scope_label} sync succeeded, but restoring snapshot "
                f"{snapshot_id} failed; the snapshot was preserved with the "
                f"unrestored changes: {details}"
            )

    remove_snapshot_anchor(repo_path, snapshot_id, scope_label)


def read_prd(prd_path):
    """Read and parse a PRD JSON file. Returns the parsed dict."""
    with open(prd_path, "r", encoding="utf-8") as f:
        return json.load(f)


def normalized_absolute_path(path):
    """Return a stable case-normalized absolute path for identity checks."""
    try:
        return os.path.normcase(str(Path(path).resolve()))
    except (OSError, RuntimeError, UnicodeError, ValueError):
        return os.path.normcase(os.path.abspath(os.path.normpath(str(path))))


def display_path(path):
    """Render a bounded, escaped local path for an operator diagnostic."""
    return bounded_failure_details(
        json.dumps(str(path), ensure_ascii=True),
        MAX_CANDIDATE_DIAGNOSTIC_PATH_LENGTH,
    )


def absolute_worktree_path(raw_path, repo_root):
    """Resolve one Git-reported worktree path without inspecting its children."""
    path = Path(raw_path)
    if not path.is_absolute():
        path = Path(repo_root) / path
    try:
        return path.resolve()
    except (OSError, RuntimeError, UnicodeError, ValueError):
        return Path(os.path.abspath(os.path.normpath(str(path))))


def canonical_packet_file_path(packet_path, worktree_path, label):
    """Validate and canonicalize one packet file before it can be consumed."""
    try:
        lexical_exists = os.path.lexists(packet_path)
    except (OSError, UnicodeError, ValueError) as error:
        raise RuntimeError(
            f"could not inspect {label.lower()} candidate "
            f"{display_path(packet_path)}: {raw_failure_details(error)}"
        ) from error
    if not lexical_exists:
        return None

    try:
        canonical_root = Path(worktree_path).resolve(strict=True)
        canonical_path = Path(packet_path).resolve(strict=True)
    except FileNotFoundError as error:
        raise RuntimeError(
            f"{label} candidate {display_path(packet_path)} could not be "
            "resolved because it is missing or contains a broken link"
        ) from error
    except (OSError, RuntimeError, UnicodeError, ValueError) as error:
        raise RuntimeError(
            f"could not resolve {label.lower()} candidate "
            f"{display_path(packet_path)}: {raw_failure_details(error)}"
        ) from error

    try:
        canonical_path.relative_to(canonical_root)
    except ValueError as error:
        raise RuntimeError(
            f"{label} candidate {display_path(packet_path)} is ineligible: "
            "its resolved path is outside the registered worktree "
            f"{display_path(canonical_root)}"
        ) from error

    try:
        is_regular_file = stat.S_ISREG(canonical_path.stat().st_mode)
    except (OSError, UnicodeError, ValueError) as error:
        raise RuntimeError(
            f"could not inspect {label.lower()} candidate "
            f"{display_path(packet_path)}: {raw_failure_details(error)}"
        ) from error
    if not is_regular_file:
        raise RuntimeError(
            f"{label} candidate {display_path(packet_path)} is ineligible: "
            "it is not a regular file"
        )

    return canonical_path


def parse_worktree_inventory(output, repo_root):
    """Parse Git's porcelain worktree inventory into bounded records."""
    blocks = []
    current = []
    for line in output.splitlines():
        if line:
            current.append(line)
        elif current:
            blocks.append(current)
            current = []
    if current:
        blocks.append(current)

    records = []
    for block in blocks:
        if not block or not block[0].startswith("worktree "):
            raise RuntimeError("git worktree inventory returned malformed output")
        raw_path = block[0][len("worktree "):]
        if not raw_path:
            raise RuntimeError("git worktree inventory returned an empty path")

        record = {
            "path": absolute_worktree_path(raw_path, repo_root),
            "branch_ref": None,
            "detached": False,
            "locked": False,
            "prunable": False,
        }
        for line in block[1:]:
            if line == "detached":
                record["detached"] = True
            elif line == "locked" or line.startswith("locked "):
                record["locked"] = True
            elif line == "prunable" or line.startswith("prunable "):
                record["prunable"] = True
            elif line.startswith("branch "):
                record["branch_ref"] = line[len("branch "):]
        records.append(record)

    if not records:
        raise RuntimeError("git worktree inventory returned no worktrees")
    return records


def list_registered_worktrees(repo_root):
    """Read Git's registered worktrees exactly once for packet discovery."""
    result = run_git(
        "worktree", "list", "--porcelain", cwd=repo_root, check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            "git worktree inventory failed "
            f"(exit {result.returncode}): {command_failure_details(result)}"
        )
    return parse_worktree_inventory(result.stdout, repo_root)


def packet_candidates(repo_root, prd_name, records):
    """Find exact packet paths under each unique registered worktree root."""
    root_key = normalized_absolute_path(repo_root)
    roots = [*records]
    if not any(normalized_absolute_path(record["path"]) == root_key for record in roots):
        roots.append(
            {
                "path": Path(repo_root),
                "branch_ref": None,
                "detached": False,
                "locked": False,
                "prunable": False,
            }
        )

    candidates = []
    seen_roots = set()
    for record in roots:
        worktree_path = record["path"]
        root_identity = normalized_absolute_path(worktree_path)
        if root_identity in seen_roots:
            continue
        seen_roots.add(root_identity)

        packet_path = worktree_path / "tasks" / "todo" / f"{prd_name}.json"
        canonical_path = canonical_packet_file_path(
            packet_path, worktree_path, "PRD JSON",
        )
        if canonical_path is not None:
            candidates.append(
                {
                    "prd_json_path": canonical_path,
                    "prd_json_candidate_path": packet_path,
                    "worktree_path": worktree_path,
                    "record": record,
                    "is_root": root_identity == root_key,
                }
            )
    return candidates


def candidate_path_details(candidates):
    """Render a bounded list of conflicting exact packet paths."""
    paths = [
        display_path(
            candidate.get("prd_json_candidate_path", candidate["prd_json_path"]),
        )
        for candidate in candidates
    ]
    if len(paths) > MAX_CANDIDATE_DIAGNOSTIC_PATHS:
        omitted = len(paths) - MAX_CANDIDATE_DIAGNOSTIC_PATHS
        paths = [*paths[:MAX_CANDIDATE_DIAGNOSTIC_PATHS], f"... ({omitted} more paths)"]
    return ", ".join(paths)


def safe_identity_display(value):
    """Render a bounded packet identity without exposing packet contents."""
    return bounded_failure_details(
        json.dumps(value, ensure_ascii=True),
        MAX_CANDIDATE_DIAGNOSTIC_PATH_LENGTH,
    )


def validate_nested_packet_freshness(repo_root, candidate, prd_name):
    """Refuse attached packets with no positive evidence of a live lane."""
    record = candidate["record"]
    packet_path = candidate["prd_json_path"]
    worktree_path = candidate["worktree_path"]
    expected_ref = f"refs/heads/{prd_name}"

    if record["locked"]:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} is ineligible: "
            "its registered worktree is locked"
        )
    if record["prunable"]:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} is ineligible: "
            "its registered worktree is prunable"
        )
    if record["detached"] or record["branch_ref"] != expected_ref:
        observed_ref = "detached" if record["detached"] else record["branch_ref"]
        observed = safe_identity_display(observed_ref) if observed_ref else "missing"
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} is ineligible: "
            f"registered worktree branch is {observed}; expected {expected_ref}"
        )
    if not (worktree_path / ".git").exists():
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} is ineligible: "
            "registered worktree path is unavailable"
        )

    has_remote_head = branch_exists_on_remote(repo_root, prd_name)
    has_origin_main = origin_main_ref_exists(repo_root)
    baseline_ref = "refs/remotes/origin/main"
    baseline_label = "origin/main"
    if not has_origin_main and local_main_ref_exists(repo_root):
        baseline_ref = "refs/heads/main"
        baseline_label = "main"
    elif not has_origin_main and has_remote_head:
        return
    elif not has_origin_main:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} cannot be correlated "
            "to a live lane: no local main baseline or remote head is "
            "available"
        )

    ahead_result = run_git(
        "rev-list", "--count", f"{baseline_ref}..{expected_ref}",
        cwd=repo_root, check=False,
    )
    if ahead_result.returncode != 0:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} freshness check failed: "
            f"{command_failure_details(ahead_result)}"
        )
    ahead_text = ahead_result.stdout.strip()
    try:
        commits_ahead = int(ahead_text)
    except ValueError as error:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} freshness check "
            f"returned an invalid commit count {safe_identity_display(ahead_text)}"
        ) from error

    if commits_ahead == 0 and not has_remote_head:
        raise RuntimeError(
            f"PRD candidate {display_path(packet_path)} appears abandoned: "
            f"the attached branch has 0 commits ahead of {baseline_label} "
            "and no remote head"
        )


def select_prd_candidate(repo_root, prd_name, records):
    """Select and validate one exact packet before any setup mutation."""
    candidates = packet_candidates(repo_root, prd_name, records)
    if not candidates:
        raise RuntimeError(
            f"PRD not found: exact tasks/todo/{prd_name}.json was absent from "
            "the main checkout and all Git-registered worktrees"
        )
    if len(candidates) > 1:
        raise RuntimeError(
            "ambiguous PRD: multiple exact candidates were found: "
            f"{candidate_path_details(candidates)}"
        )

    candidate = candidates[0]
    prd = read_prd(candidate["prd_json_path"])
    if not isinstance(prd, dict):
        raise ValueError("PRD must be a JSON object")

    packet_branch = prd.get("branchName")
    if not isinstance(packet_branch, str):
        raise ValueError("PRD branchName must be a string")
    if packet_branch != prd_name:
        raise ValueError(
            "PRD branchName mismatch: expected "
            f"{safe_identity_display(prd_name)}, observed "
            f"{safe_identity_display(packet_branch)}"
        )

    if not candidate["is_root"]:
        validate_nested_packet_freshness(repo_root, candidate, prd_name)

    packet_dir = candidate["prd_json_candidate_path"].parent
    prd_md_candidate_path = packet_dir / f"{prd_name}.md"
    prd_md_path = canonical_packet_file_path(
        prd_md_candidate_path,
        candidate["worktree_path"],
        "PRD Markdown",
    )
    candidate["prd_md_path"] = prd_md_path
    return candidate


def has_origin_remote(repo_root):
    """Return True when an origin remote is configured."""
    result = run_git("remote", "get-url", "origin", cwd=repo_root, check=False)
    return result.returncode == 0


def origin_main_ref_exists(repo_root):
    """Return True when refs/remotes/origin/main exists locally."""
    result = run_git(
        "rev-parse", "--verify", "refs/remotes/origin/main",
        cwd=repo_root, check=False,
    )
    return result.returncode == 0


def local_main_ref_exists(repo_root):
    """Return True when refs/heads/main exists locally."""
    result = run_git(
        "rev-parse", "--verify", "refs/heads/main",
        cwd=repo_root, check=False,
    )
    return result.returncode == 0


def remote_main_sha(repo_root):
    """Return origin/main sha from ls-remote, or None when missing/unreachable."""
    result = run_git(
        "ls-remote", "--exit-code", "origin", "refs/heads/main",
        cwd=repo_root, check=False,
    )
    if result.returncode != 0 or not result.stdout.strip():
        return None
    return result.stdout.strip().split()[0]


def resolve_remote_main_sha(repo_root, fetch_succeeded):
    """Resolve origin/main only when the current fetch succeeded."""
    if not fetch_succeeded:
        return None
    sha = remote_main_sha(repo_root)
    if sha is None or not immutable_object_id(sha):
        return None
    return sha


def can_fast_forward_main(repo_root, local_sha, remote_sha):
    """True when remote_sha is a strict fast-forward of local_sha."""
    if local_sha == remote_sha:
        return False
    merge_base = run_git(
        "merge-base", local_sha, remote_sha,
        cwd=repo_root, check=False,
    )
    return merge_base.returncode == 0 and merge_base.stdout.strip() == local_sha


def confirm_ref_matches(repo_path, ref_name, expected_sha):
    """Raise when ref_name does not resolve to expected_sha."""
    resolved_sha = run_git("rev-parse", ref_name, cwd=repo_path).stdout.strip()
    if resolved_sha != expected_sha:
        raise RuntimeError(
            f"{ref_name} resolved to {resolved_sha[:8]}, expected {expected_sha[:8]}"
        )


def ancestor_commit_trees(repo_path, head_sha):
    """Return reachable ancestor commit/tree pairs without per-commit Git calls."""
    result = run_git(
        "log", "--format=%H%x00%T", "--no-decorate", head_sha,
        cwd=repo_path, check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"root main sync could not inspect ancestor trees of {head_sha}: "
            f"{command_failure_details(result)}"
        )

    commit_trees = []
    for line in result.stdout.splitlines():
        values = line.split("\0")
        if len(values) != 2 or not all(immutable_object_id(value) for value in values):
            raise RuntimeError(
                f"root main sync received an invalid ancestor commit/tree pair for "
                f"{head_sha}: {line!r}"
            )
        commit, tree = values
        if commit != head_sha:
            commit_trees.append((commit, tree))
    return commit_trees


def tree_for_revision(repo_path, revision, description):
    """Return an immutable tree ID for a Git revision."""
    return require_git_output(
        run_git("rev-parse", f"{revision}^{{tree}}", cwd=repo_path, check=False),
        description,
    )


def tracked_path_summary(repo_path, head_sha, ancestor_sha):
    """Return a bounded path-only summary of the current/ancestor difference."""
    result = run_git(
        "diff", "--no-ext-diff", "--no-renames", "--name-status",
        head_sha, ancestor_sha, cwd=repo_path, check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"root main sync could not summarize ancestor residue between "
            f"{head_sha} and {ancestor_sha}: {command_failure_details(result)}"
        )

    paths = [line for line in result.stdout.splitlines() if line]
    if not paths:
        return "tracked tree differs without a named path"
    if len(paths) > MAX_ANCESTOR_RESIDUE_PATHS:
        remaining = len(paths) - MAX_ANCESTOR_RESIDUE_PATHS
        paths = [*paths[:MAX_ANCESTOR_RESIDUE_PATHS], f"... ({remaining} more paths)"]
    return ", ".join(paths)


def verify_no_ancestor_residue(repo_path):
    """Reject tracked checkout state that exactly matches an ancestor tree."""
    head_sha = require_git_output(
        run_git("rev-parse", "HEAD", cwd=repo_path, check=False),
        "root main sync could not resolve current HEAD",
    )
    head_tree = tree_for_revision(
        repo_path, head_sha, "root main sync could not capture current HEAD tree",
    )
    index_tree = require_git_output(
        run_git("write-tree", cwd=repo_path, check=False),
        "root main sync could not capture the synchronized index tree",
    )
    worktree_tree = working_tree_tree(repo_path)

    local_states = []
    if index_tree != head_tree:
        local_states.append(("index", index_tree))
    if worktree_tree != head_tree:
        local_states.append(("working tree", worktree_tree))
    if not local_states:
        return

    ancestor_trees = ancestor_commit_trees(repo_path, head_sha)
    findings = []
    for state_name, state_tree in local_states:
        for ancestor_sha, ancestor_tree in ancestor_trees:
            if state_tree == ancestor_tree:
                paths = tracked_path_summary(repo_path, head_sha, ancestor_sha)
                findings.append(
                    f"{state_name} tree {state_tree} matches ancestor "
                    f"{ancestor_sha} (tree {ancestor_tree}); paths: {paths}"
                )
                break

    if findings:
        raise RuntimeError(
            "root main post-sync ancestor-residue guard rejected tracked "
            f"local state while HEAD is {head_sha}: {' | '.join(findings)}. "
            "The checkout was not reset or cleaned; preserve it for recovery."
        )


def verify_root_after_restore(repo_root, snapshot_id):
    """Run the root residue guard and preserve a snapshot when it rejects."""
    try:
        verify_no_ancestor_residue(repo_root)
    except RuntimeError as error:
        if snapshot_id is None:
            raise RuntimeError(
                f"{error}; no root snapshot was captured for automatic recovery"
            ) from error

        recovery_ref = snapshot_ref_name(snapshot_id)
        try:
            anchor_snapshot(repo_root, snapshot_id)
        except RuntimeError as anchor_error:
            raise RuntimeError(
                f"{error}; could not preserve recovery snapshot {recovery_ref}: "
                f"{anchor_error}"
            ) from error
        raise RuntimeError(
            f"{error}; recovery snapshot preserved at {recovery_ref}"
        ) from error


def sync_checked_out_main_with_stash(repo_root, remote_sha):
    """Own, sync, and restore a checked-out root ``main`` invocation."""
    with root_sync_lock(repo_root):
        return _sync_checked_out_main_with_stash(repo_root, remote_sha)


def _sync_checked_out_main_with_stash(repo_root, remote_sha):
    """Temporarily snapshot local changes, sync main, then restore them."""
    snapshot_id = stash_local_changes(
        repo_root,
        "setup-workspace root sync",
    )
    try:
        pull_result = run_git("pull", "--ff-only", cwd=repo_root, check=False)
        if pull_result.returncode != 0:
            run_git("fetch", "origin", cwd=repo_root)
            run_git("reset", "--hard", remote_sha, cwd=repo_root)
        confirm_ref_matches(repo_root, "HEAD", remote_sha)
        confirm_ref_matches(repo_root, "refs/heads/main", remote_sha)
    finally:
        restore_stashed_changes(repo_root, snapshot_id, "root main")

    verify_root_after_restore(repo_root, snapshot_id)

    if snapshot_id is None:
        return f"synced checked-out main to {remote_sha[:8]}"
    return (
        f"stashed local changes in snapshot {snapshot_id[:8]}, "
        f"synced checked-out main to {remote_sha[:8]}, then restored the snapshot"
    )


def sync_main(repo_root):
    """Own one complete root-main synchronization invocation."""
    with root_sync_lock(repo_root):
        return _sync_main(repo_root)


def _sync_main(repo_root):
    """Best-effort root main sync without disturbing the working tree.

    Uses fetch plus refs/heads/main fast-forward when safe instead of git pull,
    so clean-root checkouts can continue workspace setup from local state.
    Dirty roots skip root synchronization after fetch when a local or remote
    main ref can provide a safe start point for the requested lane.
    Returns a string-compatible result carrying any fresh origin/main SHA.
    """
    fresh_origin_main_sha = None

    def result(message):
        return RootSyncResult(message, fresh_origin_main_sha)

    if not has_origin_remote(repo_root):
        entries = root_status_for_setup(repo_root)
        if local_main_ref_exists(repo_root):
            if entries:
                return result(
                    "skipped (dirty root; using local main without root sync)"
                )
            return result("skipped (no origin remote)")
        if entries:
            raise DirtyRootError(dirty_root_diagnostic(repo_root, entries))
        raise RuntimeError(
            "no origin remote and refs/heads/main is missing"
        )

    fetch_result = run_git("fetch", "origin", cwd=repo_root, check=False)
    fetch_succeeded = fetch_result.returncode == 0
    if not fetch_succeeded:
        if local_main_ref_exists(repo_root):
            return result(
                "skipped (fetch failed: "
                f"{command_failure_details(fetch_result)})"
            )
        if not origin_main_ref_exists(repo_root):
            entries = root_status_for_setup(repo_root)
            if entries:
                raise DirtyRootError(dirty_root_diagnostic(repo_root, entries))
            raise RuntimeError(
                "fetch failed and refs/heads/main is missing: "
                f"{command_failure_details(fetch_result)}"
            )

    remote_sha = resolve_remote_main_sha(repo_root, fetch_succeeded)
    fresh_origin_main_sha = remote_sha
    entries = root_status_for_setup(repo_root)
    if entries:
        if remote_sha is not None:
            return result(
                "skipped (dirty root; using origin/main "
                f"{remote_sha[:8]} without root sync)"
            )
        if local_main_ref_exists(repo_root):
            return result(
                "skipped (dirty root; using local main without root sync)"
            )
        raise DirtyRootError(dirty_root_diagnostic(repo_root, entries))

    if remote_sha is None:
        if local_main_ref_exists(repo_root):
            return result("skipped (origin has no main branch)")
        raise RuntimeError(
            "origin has no main branch and refs/heads/main is missing"
        )

    if not local_main_ref_exists(repo_root):
        run_git("update-ref", "refs/heads/main", remote_sha, cwd=repo_root)
        return result(f"created refs/heads/main at {remote_sha[:8]}")

    local_sha = run_git("rev-parse", "refs/heads/main", cwd=repo_root).stdout.strip()
    if local_sha == remote_sha:
        if current_branch(repo_root) == "main":
            verify_root_after_restore(repo_root, None)
        return result("already up to date")

    if not can_fast_forward_main(repo_root, local_sha, remote_sha):
        return result(
            "skipped (local main is not a fast-forward behind origin/main)"
        )

    if current_branch(repo_root) == "main":
        return result(_sync_checked_out_main_with_stash(repo_root, remote_sha))

    run_git("update-ref", "refs/heads/main", remote_sha, cwd=repo_root)
    return result(
        f"fast-forwarded refs/heads/main to {remote_sha[:8]} "
        "(fetch-only; did not run git pull)"
    )


def resolve_worktree_start_point(fresh_origin_main_sha):
    """Resolve the start point for brand-new lane branches.

    Use only the immutable SHA captured by the current successful fetch. A
    missing SHA means setup is using its existing local-main fallback; a stale
    remote-tracking ref must never become a new lane's baseline.
    """
    if fresh_origin_main_sha and immutable_object_id(fresh_origin_main_sha):
        return fresh_origin_main_sha
    return "main"


def prune_worktrees(repo_root):
    """Prune stale worktree entries."""
    run_git("worktree", "prune", cwd=repo_root)


def normalize_branch(branch_name):
    """Convert branch name to a filesystem-safe directory name."""
    return branch_name.replace("/", "-")


def worktree_is_valid(worktree_path):
    """Check if an existing worktree path is valid and has content."""
    git_file = worktree_path / ".git"
    if not git_file.exists():
        return False
    # Check for non-.git content.
    entries = [e for e in worktree_path.iterdir() if e.name != ".git"]
    return len(entries) > 0


def branch_exists_locally(repo_root, branch):
    """Check if a branch exists as a local ref."""
    result = run_git(
        "rev-parse", "--verify", f"refs/heads/{branch}",
        cwd=repo_root, check=False,
    )
    return result.returncode == 0


def branch_exists_on_remote(repo_root, branch):
    """Check if a branch exists on origin."""
    result = run_git(
        "rev-parse", "--verify", f"refs/remotes/origin/{branch}",
        cwd=repo_root, check=False,
    )
    return result.returncode == 0


def branch_upstream_ref(git_dir, branch):
    """Return upstream ref for branch, or None when no upstream is configured."""
    result = run_git(
        "rev-parse", "--abbrev-ref", f"{branch}@{{upstream}}",
        cwd=git_dir, check=False,
    )
    if result.returncode != 0:
        return None
    upstream = result.stdout.strip()
    return upstream or None


def confirm_worktree_upstream_head(worktree_path, branch, upstream_ref):
    """Raise when branch or HEAD does not match the resolved upstream sha."""
    upstream_sha = run_git("rev-parse", upstream_ref, cwd=worktree_path).stdout.strip()
    confirm_ref_matches(worktree_path, "HEAD", upstream_sha)
    confirm_ref_matches(worktree_path, f"refs/heads/{branch}", upstream_sha)


def sync_reused_worktree_branch(repo_root, worktree_path, branch):
    """Checkout branch in a reused worktree and fast-forward when safe.

    No-upstream, missing-remote-branch, and diverged-from-upstream conditions
    are all non-fatal skips: a diverged local branch keeps its worktree state
    as-is (remote commits stay on origin and reconcile at push time), because
    resetting would destroy unpushed local commits and raising would kill the
    lane. Returns a human-readable outcome string for logging.
    """
    run_git("checkout", branch, cwd=worktree_path)

    if branch_upstream_ref(worktree_path, branch) is None:
        return "skipped (no upstream configured)"

    if not branch_exists_on_remote(repo_root, branch):
        return "skipped (branch has no origin ref)"

    upstream_ref = branch_upstream_ref(worktree_path, branch)
    snapshot_id = stash_local_changes(
        worktree_path,
        f"setup-workspace worktree sync {branch}",
    )
    try:
        pull_result = run_git("pull", "--ff-only", cwd=worktree_path, check=False)
        if pull_result.returncode == 0:
            confirm_worktree_upstream_head(worktree_path, branch, upstream_ref)
            if snapshot_id is not None:
                return (
                    f"stashed local changes in snapshot {snapshot_id[:8]}, "
                    "fast-forwarded from upstream, then restored the snapshot"
                )
            return "fast-forwarded from upstream"

        stderr = pull_result.stderr.strip()
        lowered = stderr.lower()
        if "no tracking information" in lowered:
            return "skipped (no upstream configured)"

        run_git("fetch", "origin", cwd=worktree_path)
        local_sha = run_git("rev-parse", f"refs/heads/{branch}", cwd=worktree_path).stdout.strip()
        upstream_sha = run_git("rev-parse", upstream_ref, cwd=worktree_path).stdout.strip()
        if not can_fast_forward_main(worktree_path, local_sha, upstream_sha):
            if snapshot_id is not None:
                return (
                    f"stashed local changes in snapshot {snapshot_id[:8]}, "
                    "then skipped (local branch diverged from upstream; "
                    "keeping local worktree state)"
                )
            return (
                "skipped (local branch diverged from upstream; "
                "keeping local worktree state)"
            )

        run_git("reset", "--hard", upstream_ref, cwd=worktree_path)
        confirm_worktree_upstream_head(worktree_path, branch, upstream_ref)
        if snapshot_id is None:
            return "fetch/reset --hard to upstream after pull --ff-only failed"
        return (
            f"stashed local changes in snapshot {snapshot_id[:8]}, then "
            "fetch/reset --hard to upstream after pull --ff-only failed"
        )
    finally:
        restore_stashed_changes(worktree_path, snapshot_id, f"worktree branch {branch}")


def create_or_reuse_worktree(
    repo_root, branch, worktree_path, fresh_origin_main_sha=None,
):
    """Create a new worktree or reuse an existing one. Returns reused flag."""
    if worktree_path.exists() and worktree_is_valid(worktree_path):
        sync_outcome = sync_reused_worktree_branch(repo_root, worktree_path, branch)
        print(f"Worktree branch sync: {sync_outcome}", file=sys.stderr)
        return True

    # Remove stale path if it exists but is invalid.
    if worktree_path.exists():
        shutil.rmtree(worktree_path)

    # Create new worktree.
    worktree_path.parent.mkdir(parents=True, exist_ok=True)

    if branch_exists_locally(repo_root, branch):
        run_git(
            "worktree", "add", str(worktree_path), branch,
            cwd=repo_root,
        )
    elif branch_exists_on_remote(repo_root, branch):
        run_git(
            "worktree", "add", "--track", "-b", branch,
            str(worktree_path), f"origin/{branch}",
            cwd=repo_root,
        )
    else:
        run_git(
            "worktree", "add", "-b", branch, str(worktree_path),
            resolve_worktree_start_point(fresh_origin_main_sha),
            cwd=repo_root,
        )

    return False


def copy_prd_files(prd_json_path, prd_md_path, worktree_path):
    """Copy PRD files into the worktree root."""
    dest_json = worktree_path / "prd.json"
    shutil.copy2(str(prd_json_path), str(dest_json))

    dest_md = None
    if prd_md_path and prd_md_path.exists():
        dest_md = worktree_path / "prd.md"
        shutil.copy2(str(prd_md_path), str(dest_md))

    return dest_json, dest_md


# Operator-authored standing rules that lane payloads reference by this exact
# repo-relative path. The file lives under the gitignored docs/temp tree, so a
# fresh worktree never contains it and the payload pointer would dangle. Copy it
# in alongside the PRD so every lane can actually read its own rules.
STANDING_RULES_RELPATH = Path("docs") / "temp" / "scale-program-rules.md"


def copy_standing_rules(repo_root, worktree_path):
    """Copy the operator standing-rules doc into the worktree, if it exists.

    Returns the destination path, or None when the source is absent. Never
    fatal: a missing or unreadable rules doc must not block workspace setup.
    """
    source = repo_root / STANDING_RULES_RELPATH
    if not source.is_file():
        return None

    dest = worktree_path / STANDING_RULES_RELPATH
    try:
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(str(source), str(dest))
    except Exception as e:  # noqa: BLE001 - this optional copy must stay non-fatal
        print(
            format_stage_failure("Standing-rules copy skipped", e),
            file=sys.stderr,
        )
        return None

    return dest


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <prd-name>", file=sys.stderr)
        sys.exit(1)

    prd_name = sys.argv[1]

    if not prd_name:
        print("PRD name must not be empty", file=sys.stderr)
        sys.exit(1)

    try:
        repo_root = get_repo_root()
    except Exception as e:  # noqa: BLE001 - CLI boundary must classify all failures
        print(format_stage_failure("Failed to discover repo root", e), file=sys.stderr)
        sys.exit(1)

    # Discover and validate the packet before any synchronization or worktree
    # mutation. Git's registered inventory is the only supported non-root source.
    try:
        records = list_registered_worktrees(repo_root)
        selected_candidate = select_prd_candidate(repo_root, prd_name, records)
    except Exception as e:  # noqa: BLE001 - CLI boundary must classify all failures
        print(format_stage_failure("Failed to read PRD", e), file=sys.stderr)
        sys.exit(1)

    branch = f"{prd_name}"
    prd_json_path = selected_candidate["prd_json_path"]
    prd_md_path = selected_candidate["prd_md_path"]

    # Sync main and prune worktrees.
    try:
        sync_result = sync_main(repo_root)
        sync_outcome = str(sync_result)
        fresh_origin_main_sha = getattr(
            sync_result, "fresh_origin_main_sha", None,
        )
        print(f"Root sync: {sync_outcome}", file=sys.stderr)
        prune_worktrees(repo_root)
    except (DirtyRootError, RootStatusError) as e:
        print(f"Root cleanliness check failed: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:  # noqa: BLE001 - CLI boundary must classify all failures
        print(format_stage_failure("Root sync failed", e), file=sys.stderr)
        sys.exit(1)

    # Create or reuse worktree.
    if selected_candidate["is_root"]:
        worktree_dir = repo_root / ".claude" / "worktrees" / normalize_branch(branch)
    else:
        worktree_dir = selected_candidate["worktree_path"]
    try:
        reused = create_or_reuse_worktree(
            repo_root,
            branch,
            worktree_dir,
            fresh_origin_main_sha,
        )
    except Exception as e:  # noqa: BLE001 - CLI boundary must classify all failures
        print(
            format_stage_failure("Worktree preparation failed", e),
            file=sys.stderr,
        )
        sys.exit(1)

    # Copy PRD files into worktree.
    try:
        dest_json, dest_md = copy_prd_files(prd_json_path, prd_md_path, worktree_dir)
    except Exception as e:  # noqa: BLE001 - CLI boundary must classify all failures
        print(format_stage_failure("PRD copy failed", e), file=sys.stderr)
        sys.exit(1)

    # Copy the operator standing-rules doc referenced by lane payloads.
    dest_rules = copy_standing_rules(repo_root, worktree_dir)

    # Output result.
    result = {
        "status": "ready",
        "worktree": str(worktree_dir),
        "branch": branch,
        "prd_path": str(dest_json),
        "prd_md_path": str(dest_md) if dest_md else None,
        "standing_rules_path": str(dest_rules) if dest_rules else None,
        "reused": reused,
    }
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
